  /// Formats amounts using the platform's Yemeni rial display convention.
  String formatCurrency(num amount) {
    final fractionDigits = amount % 1 == 0 ? 0 : 2;
    final formatted = amount.toStringAsFixed(fractionDigits);
    return '$formatted ${locale.languageCode == 'ar' ? 'ر.ي' : 'YER'}';
  }

  /// Translates a literal Arabic UI label without network access. Unknown and
  /// user-generated content is intentionally preserved.
  String translate(String value) {
    final weeksMatch = RegExp(r'^(\d+) أسبوع و (\d+) يوم$').firstMatch(value);
    if (weeksMatch != null) {
      final weeks = weeksMatch.group(1)!;
      final days = weeksMatch.group(2)!;
      return _pick(value, '$weeks weeks and $days days', '$weeks semaines et $days jours');
    }
    final daysMatch = RegExp(r'^(\d+) يوم$').firstMatch(value);
    if (daysMatch != null) {
      final days = daysMatch.group(1)!;
      return _pick(value, '$days days', '$days jours');
    }
    const doctorWelcomePrefix = 'مرحباً دكتور ';
    if (value.startsWith(doctorWelcomePrefix)) {
      final specialty = value.substring(doctorWelcomePrefix.length);
      return _pick(value, 'Welcome, Dr. $specialty', 'Bienvenue, Dr $specialty');
    }
    const stepPrefix = 'نشاطك اليومي قريب من الهدف. تبقى ';
    const stepSuffix = ' خطوة تقريباً.';
    if (value.startsWith(stepPrefix) && value.endsWith(stepSuffix)) {
      final remaining = value.substring(stepPrefix.length, value.length - stepSuffix.length);
      return _pick(value, 'Your daily activity is close to the goal. About $remaining steps remaining.', 'Votre activité quotidienne est proche de l’objectif. Il reste environ $remaining pas.');
    }
    if (value.startsWith('تعذر إكمال عملية Google: ')) {
      final detail = value.substring('تعذر إكمال عملية Google: '.length);
      return _pick('تعذر إكمال عملية Google: ', 'Could not complete Google sign-in: ', 'Impossible de terminer la connexion Google : ') + detail;
    }
    if (value.startsWith('تعذر فتح المحادثة: ')) {
      final detail = value.substring('تعذر فتح المحادثة: '.length);
      return _pick('تعذر فتح المحادثة: ', 'Could not open chat: ', 'Impossible d’ouvrir la discussion : ') + detail;
    }

    const prescriptionPrefix = 'أضاف ';
    const prescriptionMarker = ' وصفة دوائية';
    const prescriptionSuffix = '. تم نقلها إلى تذكير الأدوية.';
    if (value.startsWith(prescriptionPrefix) && value.endsWith(prescriptionSuffix)) {
      final middle = value.substring(prescriptionPrefix.length, value.length - prescriptionSuffix.length);
      final markerIndex = middle.indexOf(prescriptionMarker);
      if (markerIndex >= 0) {
        final rawDoctor = middle.substring(0, markerIndex).trim();
        final doctor = rawDoctor == 'الطبيب'
            ? _pick('الطبيب', 'the doctor', 'le médecin')
            : rawDoctor;
        final remainder = middle.substring(markerIndex + prescriptionMarker.length).trim();
        final medications = remainder.startsWith(':') ? remainder.substring(1).trim() : '';
        final suffix = medications.isEmpty ? '' : ': $medications';
        return locale.languageCode == 'fr'
            ? '$doctor a ajouté une nouvelle ordonnance$suffix. Elle a été ajoutée aux rappels de médicaments.'
            : '$doctor added a new prescription$suffix. It has been added to medication reminders.';
      }
    }
    const verificationPrefix = 'طلب توثيق جديد لدور ';
    const verificationSuffix = ' يحتاج إلى المراجعة.';
    if (value.startsWith(verificationPrefix) && value.endsWith(verificationSuffix)) {
      final rawRole = value.substring(verificationPrefix.length, value.length - verificationSuffix.length).trim();
      final role = _translateRole(rawRole);
      return locale.languageCode == 'fr'
          ? 'Une nouvelle demande de vérification pour le rôle $role doit être examinée.'
          : 'A new verification request for the $role role needs review.';
    }
    final translations = <String, List<String>>{

      'المستخدم مشغول بمكالمة أخرى': ['The user is busy on another call', 'L’utilisateur est déjà en communication'],
      'تعذر رفض المكالمة:': ['Could not reject the call:', 'Impossible de refuser l’appel :'],
