      'منصة الرعاية الصحية الشاملة في اليمن': ['The comprehensive healthcare platform in Yemen', 'La plateforme de santé complète au Yémen'],
      'تطبيق "صحتك" هو منصة طبية متكاملة تهدف إلى تسهيل الوصول إلى الخدمات الصحية في اليمن. نوفر لك إمكانية حجز المواعيد، والاستشارات الطبية، وطلب الأدوية، ومتابعة حالتك الصحية بكل سهولة وأمان.': ['Sehatak is an integrated medical platform designed to make healthcare services in Yemen easier to access. Book appointments, consult doctors, order medicines, and manage your health with ease and confidence.', 'Sehatak est une plateforme médicale intégrée qui facilite l’accès aux services de santé au Yémen. Prenez rendez-vous, consultez des médecins, commandez des médicaments et suivez votre santé en toute simplicité et sécurité.'],
