      'التغذية الصحية': ['Healthy nutrition', 'Nutrition saine'],
      'إرشادات عملية لبناء وجبات متنوعة ومتوازنة، مع أدوات تساعدك على متابعة احتياجك.': ['Practical guidance for building varied, balanced meals, with tools to help track your needs.', 'Des conseils pratiques pour composer des repas variés et équilibrés, avec des outils pour suivre vos besoins.'],
      'هدفك': ['Your goal', 'Votre objectif'],
      'توازن غذائي': ['Balanced nutrition', 'Équilibre alimentaire'],
      'إدارة الوزن': ['Weight management', 'Gestion du poids'],
      'بناء اللياقة': ['Build fitness', 'Améliorer sa forme'],
      'الوجبات اليومية': ['Daily meals', 'Repas quotidiens'],
      'حاسبة السعرات': ['Calorie calculator', 'Calculateur de calories'],
      'الفطور': ['Breakfast', 'Petit-déjeuner'],
      'بيض أو لبن + حبوب كاملة + خضار أو فاكهة': ['Eggs or yogurt + whole grains + vegetables or fruit', 'Œufs ou yaourt + céréales complètes + légumes ou fruit'],
      'نوّع المكونات واضبط الكمية حسب احتياجك': ['Vary ingredients and adjust portions to your needs', 'Variez les ingrédients et adaptez les portions à vos besoins'],
      'الغداء': ['Lunch', 'Déjeuner'],
      'بروتين مناسب + حبوب أو نشويات + خضار': ['Suitable protein + grains or starches + vegetables', 'Protéines adaptées + céréales ou féculents + légumes'],
      'اجعل الخضار والبقوليات جزءاً متكرراً من الوجبات': ['Include vegetables and legumes regularly in meals', 'Intégrez régulièrement des légumes et des légumineuses à vos repas'],
      'العشاء': ['Dinner', 'Dîner'],
      'بروتين مناسب + خضار + مصدر حبوب مناسب': ['Suitable protein + vegetables + an appropriate grain source', 'Protéines adaptées + légumes + une source de céréales appropriée'],
      'لا تحتاج وجبة موحدة للجميع؛ راعِ احتياجك': ['There is no single meal plan for everyone; consider your needs', 'Il n’existe pas de repas unique pour tous ; tenez compte de vos besoins'],
      'وجبة خفيفة': ['Snack', 'Collation'],
      'فاكهة أو مكسرات غير مملحة أو لبن': ['Fruit, unsalted nuts, or yogurt', 'Fruit, noix non salées ou yaourt'],
      'اختر خيارات أقل في السكر المضاف والملح': ['Choose options lower in added sugar and salt', 'Choisissez des options moins riches en sucres ajoutés et en sel'],
      'طبق متوازن': ['Balanced plate', 'Assiette équilibrée'],
      'اجعل الخضروات والفواكه والحبوب الكاملة والبقوليات ومصادر البروتين ضمن تنوعك الغذائي.': ['Include vegetables, fruits, whole grains, legumes, and protein sources in your varied diet.', 'Intégrez légumes, fruits, céréales complètes, légumineuses et sources de protéines à votre alimentation variée.'],
      'اختر الدهون غير المشبعة قدر الإمكان، وقلل الملح والسكريات الحرة والمضافة.': ['Choose unsaturated fats when possible, and limit salt and free or added sugars.', 'Privilégiez les graisses insaturées et limitez le sel ainsi que les sucres libres ou ajoutés.'],
      'الماء والسوائل': ['Water and fluids', 'Eau et liquides'],
      'اجعل الماء خياراً أساسياً، وعدّل كمية السوائل وفق الجو والنشاط والحالة الصحية.': ['Make water your main choice and adjust fluid intake to the weather, activity, and health status.', 'Privilégiez l’eau et adaptez votre apport en liquides au climat, à l’activité et à votre état de santé.'],
      'لا تعتمد على المشروبات السكرية لترطيبك اليومي.': ['Do not rely on sugary drinks for daily hydration.', 'Ne comptez pas sur les boissons sucrées pour votre hydratation quotidienne.'],
      'العادات الذكية': ['Smart habits', 'Bonnes habitudes'],
      'اقرأ الملصق الغذائي عندما يكون متاحاً، وانتبه للسكر والملح والدهون المشبعة.': ['Read nutrition labels when available and watch sugar, salt, and saturated fat.', 'Lisez les étiquettes nutritionnelles et surveillez le sucre, le sel et les graisses saturées.'],
      'تجنب الحميات القاسية والمكملات غير الضرورية، ولا تستخدم مكملات علاجية دون إرشاد مناسب.': ['Avoid extreme diets and unnecessary supplements; do not use therapeutic supplements without proper guidance.', 'Évitez les régimes extrêmes et les compléments inutiles ; n’utilisez pas de compléments thérapeutiques sans conseil adapté.'],
      'الحمل والرضاعة والأطفال والأمراض المزمنة تحتاج إرشاداً غذائياً خاصاً.': ['Pregnancy, breastfeeding, children, and chronic conditions require tailored nutrition guidance.', 'La grossesse, l’allaitement, l’enfance et les maladies chroniques nécessitent des conseils nutritionnels adaptés.'],
      'متى تحتاج مختصاً؟': ['When should you see a specialist?', 'Quand consulter un spécialiste ?'],
      'فقدان أو زيادة وزن غير مقصودة، نقص غذائي مشتبه، اضطراب أكل، مرض مزمن، أو حاجة لخطة غذائية علاجية تستدعي تقييماً فردياً.': ['Unintentional weight loss or gain, suspected nutritional deficiency, eating disorder, chronic illness, or need for therapeutic diet requires individual assessment.', 'Une perte ou prise de poids involontaire, une carence suspectée, un trouble alimentaire, une maladie chronique ou un régime thérapeutique nécessitent une évaluation individuelle.'],
      'تعذر تنزيل النموذج المحلي. تحقق من الاتصال وحاول مرة أخرى.': ['Could not download the local model. Check your connection and try again.', 'Impossible de télécharger le modèle local. Vérifiez votre connexion et réessayez.'],
      'لا يوجد مسار متاح لهذه الخدمة حالياً': ['No route is currently available for this service', 'Aucun itinéraire n’est actuellement disponible pour ce service'],
      'تعذر فتح الخدمة من المسار الحالي': ['Could not open the service from the current route', 'Impossible d’ouvrir le service depuis la page actuelle'],
      'تنزيل النموذج المحلي': ['Download local model', 'Télécharger le modèle local'],
      'أعراضي': ['My symptoms', 'Mes symptômes'],
      'خدمات التطبيق': ['App services', 'Services de l’application'],
      'مساعدة': ['Help', 'Aide'],
      'يمكن تفعيل النموذج العربي المحلي من زر التنزيل أعلى الشاشة. حجمه نحو 424 MB ويُحفظ خارج التطبيق.': ['You can enable the local Arabic model using the download button above. It is about 424 MB and is stored outside the app.', 'Vous pouvez activer le modèle arabe local avec le bouton de téléchargement ci-dessus. Il fait environ 424 Mo et est stocké en dehors de l’application.'],
      'تفعيل': ['Enable', 'Activer'],
      'مركز المساعدة': ['Help center', 'Centre d’aide'],
      'فتح': ['Open', 'Ouvrir'],
      'اكتب ما تشعر به أو ما تحتاجه…': ['Describe how you feel or what you need…', 'Décrivez ce que vous ressentez ou ce dont vous avez besoin…'],
      'بدأنا محادثة جديدة. قل لي ما تشعر به أو ما تريد الوصول إليه داخل صحتك.': ['We started a new conversation. Tell me how you feel or what you want to find in Sehatak.', 'Nous avons commencé une nouvelle conversation. Dites-moi ce que vous ressentez ou ce que vous souhaitez trouver dans Sehatak.'],
