      'تم إخطار جهات الاتصال في الطوارئ والخدمات الطبية': ['Emergency contacts and medical services have been notified', 'Les contacts d’urgence et les services médicaux ont été avertis'],
      'الاتصال بالإسعاف': ['Call ambulance', 'Appeler une ambulance'],
      'كيف يمكنني حجز موعد مع طبيب؟': ['How can I book a doctor’s appointment?', 'Comment prendre rendez-vous avec un médecin ?'],
      'يمكنك حجز موعد من خلال الذهاب إلى قسم "الأطباء" واختيار الطبيب المناسب، ثم الضغط على زر "حجز موعد".': ['Go to the Doctors section, choose a suitable doctor, then select Book appointment.', 'Accédez à la section Médecins, choisissez un médecin, puis sélectionnez Prendre rendez-vous.'],
      'كيف أستخدم خدمة الاستشارة الفورية؟': ['How do I use instant consultation?', 'Comment utiliser la consultation instantanée ?'],
      'من خلال قسم "استشارة فورية" يمكنك التحدث مع طبيب عبر الدردشة النصية أو المكالمة الصوتية.': ['Use Instant consultation to speak with a doctor by text chat or voice call.', 'Utilisez la consultation instantanée pour parler à un médecin par chat ou appel vocal.'],
      'كيف أتبع حالة طلبي في الصيدلية؟': ['How do I track my pharmacy order?', 'Comment suivre ma commande en pharmacie ?'],
      'يمكنك متابعة طلبك من خلال قسم "طلباتي" في الصيدلية، حيث ستظهر لك حالة الطلب وتفاصيل التوصيل.': ['Track your order in the pharmacy’s My orders section, where its status and delivery details appear.', 'Suivez votre commande dans la section Mes commandes de la pharmacie pour consulter son statut et les détails de livraison.'],
      'كيف أضيف أفراد عائلتي للتطبيق؟': ['How do I add family members to the app?', 'Comment ajouter des membres de ma famille à l’application ?'],
      'من خلال قسم "الملف الشخصي" يمكنك إضافة أفراد العائلة وإدارة ملفاتهم الصحية.': ['Use the Profile section to add family members and manage their health records.', 'Utilisez la section Profil pour ajouter des membres de votre famille et gérer leurs dossiers médicaux.'],
      'لا توجد إشعارات': ['No notifications', 'Aucune notification'],
