      'يمكنك رفع الوصفة أو صورة الدواء وإرسال طلبك للصيدلية.': ['You can upload a prescription or medicine photo and send your request to the pharmacy.', 'Vous pouvez téléverser une ordonnance ou une photo du médicament et envoyer votre demande à la pharmacie.'],
      'التوصيل غير متاح لهذه الصيدلية حالياً.': ['Delivery is currently unavailable for this pharmacy.', 'La livraison n’est pas disponible actuellement pour cette pharmacie.'],
