      'من الملف الصحي يمكنك إضافة أفراد العائلة وإدارة بياناتهم الصحية كلٌ على حدة.': ['You can add family members from your health profile and manage each person’s health information separately.', 'Depuis votre profil santé, vous pouvez ajouter des membres de la famille et gérer séparément leurs informations médicales.'],
      'لماذا لم تصلني الإشعارات؟': ['Why am I not receiving notifications?', 'Pourquoi ne reçois-je pas les notifications ?'],
      'تأكد من اتصال الإنترنت ومن السماح للتطبيق بالإشعارات من إعدادات الهاتف، ثم أعد فتح التطبيق.': ['Check your internet connection and make sure notifications are enabled for the app in your phone settings, then reopen the app.', 'Vérifiez votre connexion Internet et autorisez les notifications de l’application dans les paramètres du téléphone, puis rouvrez l’application.'],
