      'هذه قراءة تقديرية من كاميرا الهاتف وليست بديلاً عن جهاز طبي معتمد أو تقييم الطبيب.': ['This is an estimate from the phone camera, not a substitute for a certified medical device or a clinician’s assessment.', 'Cette mesure est une estimation par la caméra du téléphone et ne remplace pas un dispositif médical certifié ni l’avis d’un professionnel de santé.'],
      'سجل قياسات النبض': ['Heart rate history', 'Historique de la fréquence cardiaque'],
