      'بعد أول قياس محفوظ ستظهر هنا الاتجاهات والإحصاءات وجودة الإشارة.': ['Trends, statistics, and signal quality will appear here after your first saved measurement.', 'Les tendances, statistiques et la qualité du signal apparaîtront après votre première mesure enregistrée.'],
