      'حاول تثبيت الإصبع وتحسين الإضاءة للحصول على قراءة أوضح.': ['Keep your finger steady and improve the lighting for a clearer reading.', 'Gardez le doigt immobile et améliorez l’éclairage pour obtenir une lecture plus claire.'],
      'يتم تحديث التحليل أثناء القياس. ثبّت إصبعك للحصول على إشارة أكثر استقراراً.': ['Analysis updates while measuring. Keep your finger steady for a more stable signal.', 'L’analyse se met à jour pendant la mesure. Gardez le doigt immobile pour un signal plus stable.'],
      'يُبنى التحليل من القياسات المحفوظة على الجهاز، ويمكنك متابعة التغيرات مع الوقت.': ['Analysis is based on measurements saved on this device; you can track changes over time.', 'L’analyse repose sur les mesures enregistrées sur cet appareil ; vous pouvez suivre leur évolution.'],
