      'جدول التطعيمات والتذكير بالمواعيد حسب عمر الطفل': ['Vaccination schedule and age-based reminders', 'Calendrier vaccinal et rappels selon l’âge de l’enfant'],
      'إرشادات الرضاعة والتغذية المتوازنة حسب المرحلة العمرية': ['Breastfeeding and balanced nutrition guidance for each age', 'Conseils sur l’allaitement et une alimentation équilibrée selon l’âge'],
