      'أفكار آمنة للحركة واللعب والتعلم حسب العمر': ['Safe age-appropriate movement, play, and learning ideas', 'Idées sûres de mouvement, de jeu et d’apprentissage adaptées à l’âge'],
      'الأمان العاطفي والسلوك والتواصل مع الطفل': ['Emotional security, behavior, and communication with your child', 'Sécurité affective, comportement et communication avec l’enfant'],
      'إرشادات عامة للتعامل مع الحالات الطارئة حتى الوصول للرعاية': ['General guidance for emergencies until professional care is available', 'Conseils généraux en cas d’urgence jusqu’à l’accès aux soins'],
      'نصائح يومية للأهل': ['Daily tips for parents', 'Conseils quotidiens aux parents'],
      'قدّم للطفل غذاءً متنوعاً ومناسباً لعمره، واهتم بالماء والنظافة.': ['Provide varied, age-appropriate food and pay attention to hydration and hygiene.', 'Proposez une alimentation variée adaptée à son âge et veillez à l’hydratation et à l’hygiène.'],
      'تابع التطعيمات والفحوصات الوقائية ولا تنتظر ظهور أعراض لإجراء المتابعة الروتينية.': ['Keep vaccinations and preventive checkups up to date; do not wait for symptoms.', 'Tenez à jour les vaccins et les bilans préventifs sans attendre l’apparition de symptômes.'],
      'وفّر بيئة آمنة للنوم واللعب، وأبعد الأدوية والمواد الخطرة عن متناول الطفل.': ['Provide a safe environment for sleep and play, and keep medicines and hazardous substances out of reach.', 'Offrez un environnement sûr pour dormir et jouer, et gardez les médicaments et produits dangereux hors de portée.'],
      'شجّع القراءة والحديث واللعب والتفاعل؛ التعلم يبدأ من السنوات الأولى.': ['Encourage reading, conversation, play, and interaction; learning begins in the early years.', 'Encouragez la lecture, la conversation, le jeu et les échanges : l’apprentissage commence dès les premières années.'],
      'راقب أي تغير مستمر في السلوك أو الحركة أو الكلام وناقشه مع طبيب الأطفال.': ['Monitor persistent changes in behavior, movement, or speech and discuss them with a pediatrician.', 'Surveillez tout changement persistant du comportement, des mouvements ou du langage et parlez-en au pédiatre.'],
      'عند وجود صعوبة تنفس أو فقدان وعي أو نزيف شديد، اطلب الطوارئ فوراً.': ['Seek emergency care immediately for breathing difficulty, loss of consciousness, or severe bleeding.', 'Appelez immédiatement les urgences en cas de difficulté respiratoire, de perte de connaissance ou de saignement important.'],
      'عناية متكاملة بطفلك': ['Complete care for your child', 'Des soins complets pour votre enfant'],
      'النمو والتطعيمات والتغذية والنوم والتعلم والسلامة في مكان واحد.': ['Growth, vaccinations, nutrition, sleep, learning, and safety in one place.', 'Croissance, vaccinations, nutrition, sommeil, apprentissage et sécurité au même endroit.'],
