      'يجب إضافة ملف الطفل أولاً من حساب العائلة': ['You must first add the child profile from the family account', 'Vous devez d’abord ajouter le profil de l’enfant depuis le compte familial'],
      'الخدمات والمتابعة': ['Services and follow-up', 'Services et suivi'],
      'هذه الشاشة مخصصة لصحة الطفل فقط. الحمل وصحة المرأة لهما شاشات مستقلة داخل صحة الأسرة.': ['This screen is dedicated to child health. Pregnancy and women’s health have separate screens in Family Health.', 'Cet écran est consacré à la santé de l’enfant. La grossesse et la santé des femmes disposent d’écrans distincts dans Santé familiale.'],
      'حسناً': ['OK', 'OK'],
      'صحة الدورة الشهرية': ['Menstrual health', 'Santé menstruelle'],
      'تسجيل الدورة والأعراض والتذكيرات الصحية': ['Track periods, symptoms, and health reminders', 'Suivi des cycles, des symptômes et des rappels de santé'],
      'الصحة الإنجابية': ['Reproductive health', 'Santé reproductive'],
      'استشارات ومعلومات عن الخصوبة وتنظيم الأسرة قبل الحمل': ['Guidance and information about fertility and family planning before pregnancy', 'Conseils et informations sur la fertilité et la planification familiale avant une grossesse'],
      'صحة الثدي': ['Breast health', 'Santé des seins'],
      'التوعية بالتغيرات التي تستدعي التقييم الطبي والفحص المناسب': ['Learn about changes that require medical assessment and appropriate screening', 'Connaître les changements nécessitant une évaluation médicale et un dépistage adapté'],
      'صحة عنق الرحم': ['Cervical health', 'Santé du col de l’utérus'],
      'التوعية بفحوصات الكشف حسب العمر والبرنامج المحلي': ['Information about screening based on age and local guidelines', 'Informations sur le dépistage selon l’âge et les recommandations locales'],
      'صحة العظام': ['Bone health', 'Santé osseuse'],
      'التغذية والنشاط والعوامل التي تدعم صحة العظام': ['Nutrition, activity, and factors that support bone health', 'Nutrition, activité et facteurs favorisant la santé osseuse'],
      'متابعة المزاج والقلق والضغط النفسي وطلب الدعم': ['Monitor mood, anxiety, and stress, and seek support', 'Suivez l’humeur, l’anxiété et le stress, et demandez de l’aide'],
      'التغذية والوزن': ['Nutrition and weight', 'Nutrition et poids'],
      'إرشادات عامة للتغذية المتوازنة والنشاط الصحي': ['General guidance on balanced nutrition and healthy activity', 'Conseils généraux pour une alimentation équilibrée et une activité saine'],
      'صحة المسالك البولية': ['Urinary tract health', 'Santé des voies urinaires'],
      'التوعية بالأعراض الشائعة ومتى يلزم الفحص الطبي': ['Learn about common symptoms and when medical evaluation is needed', 'Informations sur les symptômes courants et le moment où une consultation est nécessaire'],
      'الجلدية والشعر': ['Skin and hair', 'Peau et cheveux'],
      'العناية اليومية ومتابعة التغيرات المستمرة': ['Daily care and monitoring persistent changes', 'Soins quotidiens et suivi des changements persistants'],
      'استشارة نساء وولادة': ['Obstetrics and gynecology consultation', 'Consultation en gynécologie-obstétrique'],
      'الوصول إلى طبيبة أو اختصاصي عند الحاجة': ['Connect with a doctor or specialist when needed', 'Accédez à une médecin ou à un spécialiste si nécessaire'],
      'قياس ضغط الدم والوزن ومراجعة عوامل الخطورة ضمن الرعاية الروتينية.': ['Measure blood pressure and weight and review risk factors as part of routine care.', 'Mesurez la tension artérielle et le poids, et examinez les facteurs de risque dans le cadre du suivi habituel.'],
      'فحص سرطان عنق الرحم وفق إرشادات بلدك وعُمرك وتاريخك الصحي.': ['Cervical cancer screening according to your country’s guidelines, age, and medical history.', 'Dépistage du cancer du col selon les recommandations de votre pays, votre âge et vos antécédents médicaux.'],
      'تقييم الثدي عند ظهور كتلة أو تغير مستمر أو إفراز غير معتاد، مع الالتزام ببرامج الفحص المحلية.': ['Seek breast assessment for a lump, persistent change, or unusual discharge, and follow local screening programs.', 'Faites évaluer tout nodule, changement persistant ou écoulement inhabituel, et suivez les programmes locaux de dépistage.'],
      'فحوصات السكري والدهون وفقر الدم أو غيرها عند تحديدها حسب العمر والأعراض وعوامل الخطورة.': ['Diabetes, cholesterol, anemia, and other tests when indicated by age, symptoms, and risk factors.', 'Dépistage du diabète, du cholestérol, de l’anémie ou d’autres examens selon l’âge, les symptômes et les facteurs de risque.'],
      'مراجعة صحة الأسنان والعينين والصحة النفسية والنوم ضمن الرعاية الوقائية حسب الحاجة.': ['Review dental, eye, mental, and sleep health as part of preventive care when needed.', 'Évaluez la santé dentaire, visuelle, mentale et le sommeil dans le cadre des soins préventifs, selon les besoins.'],
      'نصائح لصحة المرأة': ['Women’s health tips', 'Conseils pour la santé des femmes'],
      'احرصي على غذاء متنوع ونشاط بدني مناسب لحالتك الصحية، وتجنبي التدخين.': ['Maintain a varied diet and physical activity suited to your health, and avoid smoking.', 'Adoptez une alimentation variée et une activité physique adaptées à votre santé, et évitez le tabac.'],
      'راجعي الأدوية والمكملات مع المختص، خصوصًا عند التخطيط للحمل أو أثناء الرضاعة.': ['Review medicines and supplements with a professional, especially when planning pregnancy or breastfeeding.', 'Vérifiez les médicaments et compléments avec un professionnel, surtout en cas de projet de grossesse ou d’allaitement.'],
      'سجلي الأعراض غير المعتادة ومدة استمرارها لتسهيل التقييم الطبي.': ['Record unusual symptoms and how long they last to support medical assessment.', 'Notez les symptômes inhabituels et leur durée pour faciliter l’évaluation médicale.'],
      'اطلبي تقييمًا طبيًا عند نزيف غير معتاد، ألم شديد أو مستمر، كتلة جديدة، أو تغير صحي مقلق.': ['Seek medical assessment for unusual bleeding, severe or persistent pain, a new lump, or a concerning health change.', 'Demandez un avis médical en cas de saignement inhabituel, de douleur intense ou persistante, de nouvelle masse ou de changement préoccupant.'],
      'استمرار الحزن أو القلق أو صعوبة أداء الحياة اليومية يستحق طلب الدعم.': ['Persistent sadness, anxiety, or difficulty with daily activities are reasons to seek support.', 'Une tristesse ou une anxiété persistante, ou des difficultés dans la vie quotidienne, justifient de demander de l’aide.'],
      'الخدمات الصحية': ['Health services', 'Services de santé'],
      'الفحوصات والمتابعة الدورية': ['Screening and routine follow-up', 'Dépistage et suivi régulier'],
      'رعاية صحية متكاملة للمرأة': ['Comprehensive women’s healthcare', 'Soins complets pour la santé des femmes'],
      'الدورة والصحة الإنجابية والثدي وعنق الرحم والعظام والصحة النفسية والرعاية الوقائية.': ['Menstrual, reproductive, breast, cervical, bone, and mental health, plus preventive care.', 'Santé menstruelle, reproductive, mammaire, cervicale, osseuse et mentale, ainsi que soins préventifs.'],
      'هذه الشاشة مخصصة لصحة المرأة العامة والوقائية. رعاية الحمل والمتابعة الأسبوعية للحمل لها شاشة مستقلة.': ['This screen covers general and preventive women’s health. Pregnancy care and weekly pregnancy follow-up have a separate screen.', 'Cet écran couvre la santé générale et préventive des femmes. Le suivi de grossesse et son suivi hebdomadaire disposent d’un écran distinct.'],
      'المحتوى توعوي ولا يستبدل التشخيص أو خطة الطبيبة.': ['This is educational content and does not replace a diagnosis or your doctor’s care plan.', 'Ce contenu est informatif et ne remplace ni un diagnostic ni le plan de soins de votre médecin.'],
      'حسنًا': ['OK', 'OK'],
      'التثقيف الصحي': ['Health education', 'Éducation à la santé'],
      'الرياضة': ['Fitness', 'Activité physique'],
      'الأمراض': ['Diseases', 'Maladies'],
      'العناية الشخصية': ['Personal care', 'Soins personnels'],
      'تمارين اليوغا للمبتدئين': ['Yoga exercises for beginners', 'Exercices de yoga pour débutants'],
      'تعلم أساسيات اليوغا مع تمارين بسيطة للمبتدئين لتحسين المرونة والاسترخاء.': ['Learn basic yoga through simple beginner exercises to improve flexibility and relaxation.', 'Apprenez les bases du yoga grâce à des exercices simples pour débutants afin d’améliorer la souplesse et la détente.'],
      'كيف تحافظ على صحة قلبك': ['How to keep your heart healthy', 'Comment préserver la santé de votre cœur'],
      'نصائح عملية للحفاظ على صحة القلب والوقاية من الأمراض القلبية.': ['Practical tips to maintain heart health and help prevent heart disease.', 'Conseils pratiques pour préserver la santé du cœur et prévenir les maladies cardiovasculaires.'],
      'أفضل 10 أطعمة لصحة الدماغ': ['Top 10 foods for brain health', 'Les 10 meilleurs aliments pour le cerveau'],
      'تعرف على الأطعمة التي تعزز صحة الدماغ وتحسن الذاكرة والتركيز.': ['Discover foods that support brain health and improve memory and focus.', 'Découvrez les aliments qui favorisent la santé du cerveau et améliorent la mémoire et la concentration.'],
      'تمارين التنفس للتخلص من التوتر': ['Breathing exercises to relieve stress', 'Exercices de respiration pour réduire le stress'],
      'تعلم تمارين التنفس العميق للتخلص من التوتر والقلق وتحسين الصحة النفسية.': ['Learn deep-breathing exercises to ease stress and anxiety and support mental well-being.', 'Apprenez des exercices de respiration profonde pour apaiser le stress et l’anxiété et favoriser le bien-être mental.'],
      'كيف تعتني ببشرتك بشكل صحيح': ['How to care for your skin properly', 'Comment bien prendre soin de sa peau'],
      'دليل شامل للعناية بالبشرة حسب نوعها مع نصائح عملية وفعالة.': ['A practical guide to skincare for different skin types, with effective tips.', 'Un guide pratique pour prendre soin des différents types de peau, avec des conseils efficaces.'],
      'التمارين المنزلية بدون أدوات': ['At-home workouts without equipment', 'Exercices à domicile sans équipement'],
      'تمارين فعالة يمكن ممارستها في المنزل بدون استخدام أي أدوات رياضية.': ['Effective exercises you can do at home without any fitness equipment.', 'Des exercices efficaces à pratiquer chez soi sans aucun équipement sportif.'],
      'أعراض نقص الفيتامينات وكيفية علاجها': ['Vitamin deficiency symptoms and how to address them', 'Symptômes des carences en vitamines et comment y remédier'],
      'تعرف على أعراض نقص الفيتامينات الشائعة وطرق علاجها الفعالة.': ['Learn about common vitamin deficiency symptoms and effective ways to address them.', 'Découvrez les symptômes courants des carences en vitamines et les moyens efficaces d’y remédier.'],
      'كيف تحسن جودة نومك': ['How to improve your sleep quality', 'Comment améliorer la qualité de votre sommeil'],
      'نصائح عملية لتحسين جودة النوم والتغلب على مشاكل الأرق واضطرابات النوم.': ['Practical tips to improve sleep quality and manage insomnia and sleep disturbances.', 'Conseils pratiques pour améliorer le sommeil et faire face à l’insomnie et aux troubles du sommeil.'],
      'التغذية السليمة للأطفال': ['Healthy nutrition for children', 'Alimentation saine pour les enfants'],
      'دليل شامل لتغذية الأطفال في مختلف المراحل العمرية لضمان نمو صحي وسليم.': ['A guide to feeding children at different ages to support healthy growth.', 'Un guide pour nourrir les enfants à chaque étape de leur développement et favoriser une croissance saine.'],
      'كيف تتعامل مع ارتفاع ضغط الدم': ['How to manage high blood pressure', 'Comment gérer l’hypertension artérielle'],
      'تعرف على طرق التعامل مع ارتفاع ضغط الدم والوقاية من مضاعفاته.': ['Learn ways to manage high blood pressure and help prevent complications.', 'Découvrez comment gérer l’hypertension artérielle et prévenir ses complications.'],
      'فوائد المشي اليومي للصحة': ['Health benefits of daily walking', 'Les bienfaits de la marche quotidienne'],
      'اكتشف فوائد المشي اليومية للصحة البدنية والنفسية وكيفية جعله جزءاً من روتينك.': ['Discover the physical and mental health benefits of daily walking and how to make it part of your routine.', 'Découvrez les bienfaits physiques et mentaux de la marche quotidienne et comment l’intégrer à votre routine.'],
      'كيف تحافظ على صحة عظامك': ['How to keep your bones healthy', 'Comment préserver la santé de vos os'],
      'نصائح للحفاظ على صحة العظام والوقاية من هشاشة العظام مع التقدم في العمر.': ['Tips to maintain bone health and help prevent osteoporosis as you age.', 'Conseils pour préserver la santé des os et prévenir l’ostéoporose avec l’âge.'],
      'تشغيل الفيديو': ['Play video', 'Lire la vidéo'],
      'سيتم إضافة فيديوهات جديدة قريباً': ['New videos will be added soon', 'De nouvelles vidéos seront bientôt ajoutées'],
      'جاري تشغيل:': ['Now playing:', 'Lecture en cours :'],
      'تعذر تحميل الملف:': ['Unable to load the profile:', 'Impossible de charger le profil :'],
      'لم يُعثر على ملف الطفل': ['Child profile not found', 'Profil de l’enfant introuvable'],
      'قدّم غذاءً متنوعاً ومناسباً للعمر. تجنب العسل قبل عمر سنة وانتبه لمخاطر الاختناق.': ['Offer a varied, age-appropriate diet. Avoid honey before 12 months and watch for choking hazards.', 'Proposez une alimentation variée adaptée à l’âge. Évitez le miel avant 12 mois et soyez attentif aux risques d’étouffement.'],
      ' ساعة خلال 24 ساعة.': [' hours in 24 hours.', ' heures sur 24.'],
      'ابدأ العناية بالفم مبكراً واستخدم معجون فلورايد بكمية مناسبة للعمر وفق إرشادات طبيب الأسنان.': ['Start oral care early and use an age-appropriate amount of fluoride toothpaste as advised by a dentist.', 'Commencez les soins bucco-dentaires tôt et utilisez une quantité de dentifrice fluoré adaptée à l’âge, selon les conseils du dentiste.'],
      'تابع بطاقة التطعيم وجدول وزارة الصحة؛ الجرعات والمواعيد تختلف حسب البرنامج الوطني وحالة الطفل.': ['Follow the vaccination card and Ministry of Health schedule; doses and timing vary by national program and the child’s circumstances.', 'Suivez le carnet de vaccination et le calendrier du ministère de la Santé ; les doses et les dates varient selon le programme national et la situation de l’enfant.'],
      'الوزن:': ['Weight:', 'Poids :'],
      'الطول:': ['Height:', 'Taille :'],
      'محيط الرأس:': ['Head circumference:', 'Périmètre crânien :'],
      'تابع النمو والتغذية والتطور والسمع والنظر وصحة الفم ضمن الزيارات الوقائية المناسبة للعمر.': ['Monitor growth, nutrition, development, hearing, vision, and oral health during age-appropriate preventive visits.', 'Suivez la croissance, la nutrition, le développement, l’audition, la vue et la santé bucco-dentaire lors des visites préventives adaptées à l’âge.'],
      'راجع الطبيب عند وجود مشكلة مستمرة في الرؤية أو السمع أو صعوبة تتبع الأشياء أو الاستجابة للأصوات.': ['Consult a doctor for persistent vision or hearing problems, difficulty tracking objects, or responding to sounds.', 'Consultez un médecin en cas de problèmes persistants de vue ou d’audition, de difficulté à suivre des objets ou à réagir aux sons.'],
      'شجّع الحركة واللعب والتفاعل المناسب للعمر وتحت إشراف آمن.': ['Encourage age-appropriate movement, play, and interaction with safe supervision.', 'Encouragez les mouvements, les jeux et les interactions adaptés à l’âge, sous une surveillance appropriée.'],
      'روتين واضح واستماع واحتواء ولعب وتواصل يومي يدعم الصحة النفسية.': ['Consistent routines, listening, reassurance, play, and daily communication support mental well-being.', 'Des routines régulières, l’écoute, le réconfort, le jeu et la communication quotidienne favorisent le bien-être mental.'],
      'في صعوبة التنفس أو فقدان الوعي أو نزيف شديد اطلب الطوارئ فوراً. إسعافات الاختناق والحروق تختلف حسب العمر وشدة الحالة.': ['For difficulty breathing, loss of consciousness, or severe bleeding, seek emergency help immediately. First aid for choking and burns depends on age and severity.', 'En cas de difficulté respiratoire, de perte de connaissance ou de saignement important, appelez immédiatement les urgences. Les premiers secours en cas d’étouffement ou de brûlure dépendent de l’âge et de la gravité.'],
      'محتوى القسم غير متوفر.': ['Section content is unavailable.', 'Le contenu de cette rubrique est indisponible.'],
      'المعلومات للتثقيف والمتابعة ولا تغني عن تقييم طبيب الأطفال عند الحاجة.': ['This information is for education and monitoring and does not replace assessment by a pediatrician when needed.', 'Ces informations sont destinées à l’éducation et au suivi et ne remplacent pas l’évaluation d’un pédiatre si nécessaire.'],
