      'جلسة تنفس موجهة مع مؤقت': ['Guided breathing session with a timer', 'Séance de respiration guidée avec minuterie'],
      'دعم وإرشاد': ['Support and guidance', 'Soutien et accompagnement'],
      'الوصول إلى الأطباء والمختصين المتاحين': ['Access available doctors and specialists', 'Accès aux médecins et spécialistes disponibles'],
