      'الحركة والتواصل': ['Movement and connection', 'Activité et relations sociales'],
      'نشاط بدني مناسب وتواصل داعم مع أشخاص تثق بهم قد يساعدان على تحسين الرفاه النفسي.': ['Appropriate physical activity and supportive contact with people you trust may improve mental well-being.', 'Une activité physique adaptée et des échanges bienveillants avec des personnes de confiance peuvent améliorer le bien-être mental.'],
      'إدارة الضغط': ['Stress management', 'Gestion du stress'],
      'قسّم المهام الكبيرة، خذ فواصل قصيرة، واستخدم تمارين التنفس عند الشعور بالتوتر.': ['Break large tasks into smaller steps, take short breaks, and use breathing exercises when stressed.', 'Divisez les grandes tâches en étapes, faites de courtes pauses et pratiquez des exercices de respiration en cas de stress.'],
      'متى تطلب المساعدة؟': ['When should you seek help?', 'Quand demander de l’aide ?'],
      'إذا استمرت الأعراض أو أثرت في النوم أو العمل أو الدراسة أو العلاقات، تحدث مع مختص.': ['If symptoms persist or affect sleep, work, study, or relationships, talk to a professional.', 'Si les symptômes persistent ou affectent le sommeil, le travail, les études ou les relations, parlez-en à un professionnel.'],
      'تنبيه مهم: الأدوات والتقييمات للتوعية والمتابعة الذاتية وليست تشخيصاً أو بديلاً عن العلاج. عند وجود خطر فوري على النفس أو الآخرين، اطلب المساعدة الطارئة المحلية فوراً.': ['Important: These tools and assessments are for education and self-monitoring, not diagnosis or a substitute for treatment. If there is an immediate risk to yourself or others, seek local emergency help immediately.', 'Important : ces outils et évaluations servent à l’information et à l’auto-suivi ; ils ne constituent pas un diagnostic ni un remplacement des soins. En cas de danger immédiat pour vous-même ou autrui, contactez immédiatement les services d’urgence locaux.'],
      'مساحة آمنة للعناية بنفسك': ['A safe space to care for yourself', 'Un espace sûr pour prendre soin de vous'],
      'توعية، متابعة يومية، تمارين استرخاء، وإمكانية الوصول إلى مختص عند الحاجة.': ['Education, daily tracking, relaxation exercises, and access to a professional when needed.', 'Information, suivi quotidien, exercices de relaxation et accès à un professionnel si nécessaire.'],
      'استعد': ['Get ready', 'Préparez-vous'],
      'متوقف مؤقتاً': ['Paused', 'En pause'],
      'شهيق ببطء': ['Breathe in slowly', 'Inspirez lentement'],
      'زفير ببطء': ['Breathe out slowly', 'Expirez lentement'],
      'اكتملت الجلسة': ['Session complete', 'Séance terminée'],
      'تمارين التنفس والاسترخاء': ['Breathing and relaxation exercises', 'Exercices de respiration et de relaxation'],
      'جلسة قصيرة للتنفس الهادئ. اجلس في وضع مريح واترك التنفس طبيعياً دون إجبار.': ['A short calming breathing session. Sit comfortably and let your breathing remain natural; do not force it.', 'Une courte séance de respiration apaisante. Asseyez-vous confortablement et respirez naturellement, sans forcer.'],
      'نمط الجلسة: 4 ثوانٍ شهيق ثم 4 ثوانٍ زفير. أوقف التمرين إذا شعرت بدوخة أو ضيق نفس.': ['Session pattern: inhale for 4 seconds, then exhale for 4 seconds. Stop if you feel dizzy or short of breath.', 'Rythme de la séance : inspirez pendant 4 secondes, puis expirez pendant 4 secondes. Arrêtez si vous ressentez des vertiges ou un essoufflement.'],
      'إيقاف مؤقت': ['Pause', 'Mettre en pause'],
      'بدء التمرين': ['Start exercise', 'Commencer l’exercice'],
      'إعادة الجلسة': ['Restart session', 'Recommencer la séance'],
      'النوم الموصى به يعتمد على العمر: ': ['Recommended sleep depends on age:', 'Le sommeil recommandé dépend de l’âge :'],
      'ساعة خلال 24 ساعة.': ['hours in 24 hours.', 'heures sur 24.'],
      'سم': ['cm', 'cm'],
      'خلال الأيام الأخيرة، هل شعرت بتوتر أو قلق يعيق يومك؟': ['In recent days, have you felt stress or anxiety that interfered with your day?', 'Ces derniers jours, avez-vous ressenti un stress ou une anxiété qui a perturbé votre journée ?'],
      'هل واجهت صعوبة متكررة في النوم أو الاسترخاء؟': ['Have you repeatedly had difficulty sleeping or relaxing?', 'Avez-vous eu à plusieurs reprises des difficultés à dormir ou à vous détendre ?'],
      'هل فقدت الاهتمام بأشياء كنت تستمتع بها؟': ['Have you lost interest in things you used to enjoy?', 'Avez-vous perdu l’intérêt pour des activités que vous aimiez auparavant ?'],
      'هل أثرت مشاعرك في العمل أو الدراسة أو علاقاتك؟': ['Have your feelings affected your work, studies, or relationships?', 'Vos émotions ont-elles affecté votre travail, vos études ou vos relations ?'],
      'هل شعرت بصعوبة في التعامل مع ضغوطك اليومية؟': ['Have you found it difficult to cope with everyday pressures?', 'Avez-vous eu du mal à faire face aux pressions quotidiennes ?'],
      'هل تشعر أنك تحتاج إلى دعم نفسي أو شخص تتحدث معه؟': ['Do you feel you need emotional support or someone to talk to?', 'Pensez-vous avoir besoin d’un soutien psychologique ou de quelqu’un à qui parler ?'],
      'أبداً': ['Never', 'Jamais'],
      'أحياناً': ['Sometimes', 'Parfois'],
      'غالباً': ['Often', 'Souvent'],
      'تقريباً كل يوم': ['Almost every day', 'Presque tous les jours'],
      'استبيان توعوي': ['Educational questionnaire', 'Questionnaire informatif'],
      'أجب عن كل سؤال وفق ما ينطبق عليك خلال الفترة الأخيرة.': ['Answer each question based on how you have felt recently.', 'Répondez à chaque question selon ce que vous avez ressenti récemment.'],
      'سؤال ': ['Q', 'u'],
      'هذا الاستبيان لا يشخّص الاكتئاب أو القلق أو أي اضطراب نفسي.': ['This questionnaire does not diagnose depression, anxiety, or any mental health condition.', 'Ce questionnaire ne diagnostique ni la dépression, ni l’anxiété, ni aucun trouble mental.'],
      'مؤشر منخفض في هذا الاستبيان': ['Low indicator on this questionnaire', 'Indicateur faible dans ce questionnaire'],
      'مؤشر متوسط في هذا الاستبيان': ['Moderate indicator on this questionnaire', 'Indicateur modéré dans ce questionnaire'],
      'مؤشر مرتفع في هذا الاستبيان': ['High indicator on this questionnaire', 'Indicateur élevé dans ce questionnaire'],
      'ملخص التقييم': ['Assessment summary', 'Résumé de l’évaluation'],
      'من ': ['o', 'u'],
      'النتيجة مؤشر توعوي وليست تشخيصاً. إذا كانت الأعراض مستمرة أو تؤثر في حياتك، ناقشها مع مختص. عند وجود خطر فوري على النفس أو الآخرين، اطلب المساعدة الطارئة المحلية فوراً.': ['This result is an educational indicator, not a diagnosis. If symptoms persist or affect your life, discuss them with a professional. If there is immediate danger to yourself or others, seek local emergency help immediately.', 'Ce résultat est un indicateur informatif et non un diagnostic. Si les symptômes persistent ou affectent votre vie, parlez-en à un professionnel. En cas de danger immédiat pour vous-même ou autrui, contactez immédiatement les services d’urgence locaux.'],
