      'ملاحظات اليوم': ['Today’s notes', 'Notes du jour'],
      'اكتب ما تريد تذكره...': ['Write anything you want to remember...', 'Écrivez ce que vous souhaitez retenir…'],
      'حفظ الحالة': ['Save entry', 'Enregistrer'],
      'التتبع يساعدك على ملاحظة الأنماط مع الوقت، لكنه ليس أداة لتشخيص الاكتئاب أو أي اضطراب نفسي.': ['Tracking can help you notice patterns over time, but it is not a tool for diagnosing depression or any mental health condition.', 'Le suivi peut vous aider à repérer des tendances au fil du temps, mais il ne permet pas de diagnostiquer la dépression ni aucun trouble mental.'],
