      'سجّل ليلة كاملة أولاً للحصول على تحليل مبني على بيانات نومك.': ['Record a full night first to get an analysis based on your sleep data.', 'Enregistrez d’abord une nuit complète pour obtenir une analyse fondée sur vos données de sommeil.'],
      'مدة النوم المسجلة أقل من 7 ساعات. راقب هذا الاتجاه عبر عدة ليالٍ وحافظ على روتين نوم منتظم.': ['Recorded sleep duration is under 7 hours. Monitor this trend over several nights and maintain a regular sleep routine.', 'La durée de sommeil enregistrée est inférieure à 7 heures. Suivez cette tendance sur plusieurs nuits et gardez une routine régulière.'],
      'الكفاءة المسجلة جيدة. استمر على روتين ثابت وراقب توزيع المراحل مع مرور الأيام.': ['Recorded sleep efficiency is good. Keep a consistent routine and monitor stage distribution over time.', 'L’efficacité du sommeil enregistrée est bonne. Gardez une routine régulière et surveillez la répartition des phases au fil du temps.'],
      'هناك مساحة لتحسين انتظام النوم. راقب وقت الاستغراق والاستيقاظ وتكرار فترات اليقظة.': ['There is room to improve sleep regularity. Monitor sleep onset, wake-up time and awake periods.', 'La régularité du sommeil peut être améliorée. Surveillez l’endormissement, l’heure du réveil et les périodes d’éveil.'],
