      'DASS-21 المعدل': ['Modified DASS-21', 'DASS-21 modifié'],
      'عن الاختبار': ['About the test', 'À propos du test'],
      '• 15 سؤالاً لقياس مستوى التوتر': ['• 15 questions to assess stress levels', '• 15 questions pour évaluer le niveau de stress'],
      '• مدة الاختبار: 3-5 دقائق': ['• Test duration: 3–5 minutes', '• Durée du test : 3 à 5 minutes'],
      '• يعتمد على مقياس DASS-21 العلمي': ['• Based on the scientific DASS-21 scale', '• Basé sur l’échelle scientifique DASS-21'],
      '• هذا اختبار مساعد فقط وليس تشخيصاً طبياً': ['• This is a supportive screening tool, not a medical diagnosis', '• Cet outil est indicatif et ne constitue pas un diagnostic médical'],
      'مستويات النتائج': ['Result levels', 'Niveaux de résultats'],
      'منخفض (0-20)': ['Low (0–20)', 'Faible (0–20)'],
      'حالتك النفسية جيدة. استمر في عاداتك الصحية.': ['Your psychological well-being appears good. Maintain your healthy habits.', 'Votre bien-être psychologique semble bon. Gardez vos habitudes saines.'],
      'متوسط (21-50)': ['Moderate (21–50)', 'Modéré (21–50)'],
      'لديك بعض التوتر. جرب تقنيات الاسترخاء.': ['You may be experiencing some stress. Try relaxation techniques.', 'Vous ressentez peut-être un certain stress. Essayez des techniques de relaxation.'],
      'مرتفع (51-80)': ['High (51–80)', 'Élevé (51–80)'],
      'مستوى توتر مرتفع. ننصح باستشارة مختص.': ['Stress levels are high. Consider consulting a professional.', 'Le niveau de stress est élevé. Envisagez de consulter un spécialiste.'],
      'شديد (81+)': ['Severe (81+)', 'Sévère (81+)'],
      'توتر شديد. يرجى التواصل مع أخصائي نفسي.': ['Severe stress. Please contact a mental health professional.', 'Stress sévère. Veuillez contacter un professionnel de la santé mentale.'],
      'ابدأ الاختبار': ['Start the test', 'Commencer le test'],
      'يرجى الإجابة على جميع الأسئلة': ['Please answer all questions', 'Veuillez répondre à toutes les questions'],
      'دائماً': ['Always', 'Toujours'],
      'تمت الإجابة': ['answered', 'répondues'],
      'عرض النتيجة': ['View results', 'Voir les résultats'],
      'مستوى التوتر': ['Stress level', 'Niveau de stress'],
      'نقطة': ['points', 'points'],
