      'إعادة الاختبار': ['Retake the test', 'Refaire le test'],
      'استشر مختص': ['Consult a specialist', 'Consulter un spécialiste'],
      'أشعر بالتوتر والقلق معظم الوقت': ['I feel stressed and anxious most of the time', 'Je me sens stressé et anxieux la plupart du temps'],
      'أجد صعوبة في النوم أو الاستمرار في النوم': ['I have difficulty falling asleep or staying asleep', 'J’ai du mal à m’endormir ou à rester endormi'],
      'أشعر بالإرهاق والتعب بدون سبب واضح': ['I feel exhausted and tired without a clear reason', 'Je me sens épuisé et fatigué sans raison apparente'],
      'أجد صعوبة في التركيز على المهام اليومية': ['I have difficulty concentrating on daily tasks', 'J’ai du mal à me concentrer sur les tâches quotidiennes'],
      'أشعر بسرعة الانفعال والغضب من أبسط الأمور': ['I become irritated or angry over the smallest things', 'Je m’irrite ou me mets en colère pour des choses insignifiantes'],
      'فقدت الاهتمام بالأنشطة التي كنت أستمتع بها': ['I have lost interest in activities I used to enjoy', 'J’ai perdu intérêt pour les activités que j’aimais auparavant'],
      'أشعر بآلام جسدية (صداع، ظهر، معدة) بدون سبب طبي': ['I experience physical pain (headaches, back or stomach pain) without a medical cause', 'Je ressens des douleurs physiques (maux de tête, dos ou ventre) sans cause médicale'],
      'تغيرت شهيتي بشكل ملحوظ (زيادة أو نقصان)': ['My appetite has changed noticeably (increased or decreased)', 'Mon appétit a nettement changé (augmentation ou diminution)'],
      'أشعر بالعزلة والوحدة حتى مع وجود الآخرين': ['I feel isolated and lonely even when others are around', 'Je me sens isolé et seul même lorsque d’autres personnes sont présentes'],
      'أجد صعوبة في اتخاذ القرارات البسيطة': ['I have difficulty making simple decisions', 'J’ai du mal à prendre des décisions simples'],
      'أشعر بأن الأمور خارجة عن السيطرة': ['I feel that things are out of control', 'J’ai l’impression que les choses échappent à mon contrôle'],
      'أستيقظ متعباً حتى بعد النوم الكافي': ['I wake up tired even after getting enough sleep', 'Je me réveille fatigué même après avoir suffisamment dormi'],
      'أشعر بالخوف من المستقبل باستمرار': ['I constantly feel afraid of the future', 'J’ai constamment peur de l’avenir'],
      'أفقد أعصابي بسهولة مع العائلة والأصدقاء': ['I lose my temper easily with family and friends', 'Je perds facilement patience avec ma famille et mes amis'],
      'أشعر أن الضغوط تفوق قدرتي على التحمل': ['I feel that the pressure is beyond what I can handle', 'J’ai l’impression que la pression dépasse mes capacités'],
      '• أنت في حالة جيدة! استمر في نمط حياتك الصحي': ['• You seem to be doing well. Maintain your healthy lifestyle.', '• Vous semblez aller bien. Continuez votre mode de vie sain.'],
      '• مارس التأمل والاسترخاء بانتظام': ['• Practice mindfulness and relaxation regularly', '• Pratiquez régulièrement la pleine conscience et la relaxation'],
      '• حافظ على توازن العمل والحياة': ['• Maintain a healthy work–life balance', '• Maintenez un bon équilibre entre vie professionnelle et vie personnelle'],
      '• خذ استراحة قصيرة كل ساعة عمل': ['• Take a short break every hour of work', '• Faites une courte pause chaque heure de travail'],
      '• مارس الرياضة 30 دقيقة يومياً': ['• Exercise for 30 minutes daily', '• Faites 30 minutes d’exercice par jour'],
      '• تحدث مع صديق تثق به عن مشاعرك': ['• Talk about your feelings with a trusted friend', '• Parlez de vos sentiments à un ami de confiance'],
      '• جرب تمارين التنفس العميق': ['• Try deep-breathing exercises', '• Essayez des exercices de respiration profonde'],
      '• ننصحك بمراجعة أخصائي نفسي': ['• We recommend consulting a mental health professional', '• Nous vous recommandons de consulter un professionnel de la santé mentale'],
      '• قلل من الكافيين والمنبهات': ['• Reduce caffeine and stimulants', '• Réduisez la caféine et les stimulants'],
      '• نظم وقتك وحدد أولوياتك': ['• Organize your time and set priorities', '• Organisez votre temps et définissez vos priorités'],
      '• مارس تمارين الاسترخاء والتأمل': ['• Practice relaxation and meditation exercises', '• Pratiquez des exercices de relaxation et de méditation'],
      '• احصل على قسط كاف من النوم': ['• Get enough sleep', '• Dormez suffisamment'],
      '• تواصل مع أخصائي نفسي في أقرب وقت': ['• Contact a mental health professional as soon as possible', '• Contactez un professionnel de la santé mentale dès que possible'],
      '• لا تتردد في طلب المساعدة': ['• Do not hesitate to ask for help', '• N’hésitez pas à demander de l’aide'],
      '• تحدث مع شخص تثق به': ['• Talk to someone you trust', '• Parlez à une personne de confiance'],
      '• خذ إجازة للراحة والاستجمام': ['• Take time off to rest and recharge', '• Prenez du temps pour vous reposer et vous ressourcer'],
      '• تذكر أن الصحة النفسية مثل الجسدية تماماً': ['• Remember that mental health is just as important as physical health', '• N’oubliez pas que la santé mentale est aussi importante que la santé physique'],
      'نتيجتك تشير إلى مستوى توتر منخفض. أنت تتعامل مع الضغوط بشكل جيد. حافظ على نمط حياتك الصحي.': ['Your result suggests a low stress level. You are managing pressure well. Maintain your healthy lifestyle.', 'Votre résultat indique un faible niveau de stress. Vous gérez bien la pression. Gardez votre mode de vie sain.'],
      'نتيجتك تشير إلى مستوى توتر متوسط. قد تحتاج إلى بعض تقنيات الاسترخاء وإدارة الوقت.': ['Your result suggests moderate stress. Relaxation and time-management techniques may help.', 'Votre résultat indique un stress modéré. Des techniques de relaxation et de gestion du temps peuvent aider.'],
      'نتيجتك تشير إلى مستوى توتر مرتفع. ننصحك بالتحدث مع مختص نفسي ومنصة تقنيات إدارة التوتر.': ['Your result suggests high stress. Consider speaking with a mental health professional and learning stress-management techniques.', 'Votre résultat indique un stress élevé. Envisagez de consulter un professionnel et d’apprendre des techniques de gestion du stress.'],
      'نتيجتك تشير إلى مستوى توتر شديد. ننصحك بشدة بالتواصل مع أخصائي نفسي في أقرب وقت. أنت لست وحدك.': ['Your result suggests severe stress. We strongly recommend contacting a mental health professional soon. You are not alone.', 'Votre résultat indique un stress sévère. Nous vous recommandons vivement de contacter rapidement un professionnel. Vous n’êtes pas seul.'],
      'مرحباً! أنا المساعد الطبي العصبي. اكتب استفسارك وسأحلله محلياً.': ['Hello! I am the neural medical assistant. Enter your question and I will analyze it locally.', 'Bonjour ! Je suis l’assistant médical neuronal. Saisissez votre question et je l’analyserai localement.'],
      'تعذر تحليل الرسالة حالياً.': ['The message could not be analyzed right now.', 'Le message ne peut pas être analysé pour le moment.'],
      'المساعد الطبي العصبي': ['Neural medical assistant', 'Assistant médical neuronal'],
      'ما هو دواء الباراسيتامول؟': ['What is paracetamol?', 'Qu’est-ce que le paracétamol ?'],
      'ماذا أفعل في حالة الحروق؟': ['What should I do in case of burns?', 'Que dois-je faire en cas de brûlure ?'],
      'مرحباً! 👋\\nأنا المساعد الصحي الذكي. اسألني عن الأدوية، الأمراض، الإسعافات الأولية أو النصائح الصحية.': ['Hello! 👋\\nI am your smart health assistant. Ask me about medicines, illnesses, first aid, or health advice.', 'Bonjour ! 👋\\nJe suis votre assistant santé intelligent. Posez vos questions sur les médicaments, les maladies, les premiers secours ou les conseils de santé.'],
      'تعذر إنشاء الرد حالياً. حاول مرة أخرى.': ['Could not generate a response right now. Please try again.', 'Impossible de générer une réponse pour le moment. Réessayez.'],
      'يعمل دون اتصال بالإنترنت ويحفظ المحادثة محلياً': ['Works offline and saves the conversation locally', 'Fonctionne hors ligne et enregistre la conversation localement'],
      'استشارة طارئة': ['Emergency consultation', 'Consultation d’urgence'],
      'لحالات الطوارئ، اتصل على 1122 فوراً': ['For emergencies, call 1122 immediately', 'En cas d’urgence, appelez immédiatement le 1122'],
      'درجة الاستعجال': ['Urgency level', 'Niveau d’urgence'],
      'خلال 24 ساعة': ['Within 24 hours', 'Dans les 24 heures'],
      'عاجل': ['Urgent', 'Urgent'],
      'وصف الحالة': ['Describe the condition', 'Description de l’état'],
      'صف الأعراض التي تعاني منها...': ['Describe the symptoms you are experiencing...', 'Décrivez les symptômes que vous ressentez...'],
      'إرسال صور': ['Send photos', 'Envoyer des photos'],
      'صور للمنطقة المصابة': ['Photos of the affected area', 'Photos de la zone touchée'],
      'مشاركة موقعي': ['Share my location', 'Partager ma position'],
      'لتحديد أقرب مستشفى': ['To locate the nearest hospital', 'Pour localiser l’hôpital le plus proche'],
      'خذ قسطاً من الراحة. ضع كمادات باردة. اشرب الماء.': ['Get some rest. Apply a cold compress and drink water.', 'Reposez-vous. Appliquez une compresse froide et buvez de l’eau.'],
      'جرح': ['Wound', 'Plaie'],
      'اغسل الجرح بماء نظيف. اضغط لوقف النزيف. طهره وغطه بضمادة.': ['Wash the wound with clean water. Apply pressure to stop bleeding, clean it, and cover it with a dressing.', 'Lavez la plaie à l’eau propre. Comprimez pour arrêter le saignement, désinfectez et couvrez avec un pansement.'],
      'حرق': ['Burn', 'Brûlure'],
      'ضع تحت ماء بارد 20 دقيقة. غطِّ بضمادة معقمة.': ['Cool under running water for 20 minutes. Cover with a sterile dressing.', 'Refroidissez sous l’eau courante pendant 20 minutes. Couvrez avec un pansement stérile.'],
      'قس حرارتك. اشرب سوائل. خذ بار.ييتامول فوق 38.5.': ['Check your temperature and drink fluids. Seek medical advice before taking fever medicine.', 'Prenez votre température et buvez des liquides. Demandez un avis médical avant de prendre un médicament contre la fièvre.'],
      'اشرب محاليل الجفاف. تجنب الألبان. كل الموز والأرز.': ['Drink oral rehydration solution. Avoid dairy products. Eat bananas and rice.', 'Buvez une solution de réhydratation orale. Évitez les produits laitiers. Mangez des bananes et du riz.'],
      'لدغة': ['Bite or sting', 'Piqûre'],
      'اغسل المكان. ضع كمادات باردة. راقب علامات التحسس.': ['Wash the area. Apply a cold compress and watch for signs of an allergic reaction.', 'Lavez la zone. Appliquez une compresse froide et surveillez les signes de réaction allergique.'],
      'يرجى استشارة الطبيب للتشخيص الدقيق.': ['Please consult a doctor for an accurate diagnosis.', 'Veuillez consulter un médecin pour un diagnostic précis.'],
      'المسعف الشخصي ⛑️': ['Personal first-aid assistant ⛑️', 'Assistant de premiers secours personnel ⛑️'],
      '...يكتب': ['...is typing', '...écrit'],
      'صف حالتك...': ['Describe your condition...', 'Décrivez votre état...'],
      'تم حفظ الإعدادات والاتصال بالخادم': ['Settings saved and connected to the server', 'Paramètres enregistrés et connexion au serveur établie'],
      'تم حفظ الإعدادات ولكن لا يمكن الاتصال بالخادم': ['Settings saved, but the server could not be reached', 'Paramètres enregistrés, mais le serveur est inaccessible'],
      'فشل حفظ الإعدادات:': ['Failed to save settings:', 'Échec de l’enregistrement des paramètres :'],
      'إعدادات Nextcloud': ['Nextcloud settings', 'Paramètres Nextcloud'],
      '☁️ Nextcloud مفتوح المصدر': ['☁️ Open-source Nextcloud', '☁️ Nextcloud open source'],
      'Nextcloud هو خادم مفتوح المصدر بالكامل، يمكنك تثبيته على خادمك الخاص.\n\n✅ مجاني 100%\n✅ لا يحتاج مفاتيح API\n✅ بياناتك ملكك أنت فقط\n✅ يمكن تثبيته على أي خادم': ['Nextcloud is fully open source and can be installed on your own server.\n\n✅ 100% free\n✅ No API keys required\n✅ Your data belongs to you\n✅ Can be installed on any server', 'Nextcloud est entièrement open source et peut être installé sur votre propre serveur.\n\n✅ 100 % gratuit\n✅ Aucune clé API requise\n✅ Vos données vous appartiennent\n✅ Installable sur tout serveur'],
      'متصل بخادم Nextcloud': ['Connected to the Nextcloud server', 'Connecté au serveur Nextcloud'],
      'غير متصل بخادم Nextcloud': ['Not connected to the Nextcloud server', 'Non connecté au serveur Nextcloud'],
      'عنوان خادم Nextcloud': ['Nextcloud server address', 'Adresse du serveur Nextcloud'],
      'أدخل عنوان IP أو دومين الخادم الخاص بك': ['Enter your server IP address or domain', 'Saisissez l’adresse IP ou le nom de domaine de votre serveur'],
      'يرجى إدخال عنوان الخادم': ['Please enter the server address', 'Veuillez saisir l’adresse du serveur'],
      'اسم المستخدم الذي أنشأته في Nextcloud': ['The username you created in Nextcloud', 'Le nom d’utilisateur que vous avez créé dans Nextcloud'],
      'يرجى إدخال اسم المستخدم': ['Please enter a username', 'Veuillez saisir un nom d’utilisateur'],
      'كلمة مرور مستخدم Nextcloud': ['Your Nextcloud user password', 'Le mot de passe de votre compte Nextcloud'],
      'يرجى إدخال كلمة المرور': ['Please enter a password', 'Veuillez saisir un mot de passe'],
      'منذ 10 دقائق': ['10 minutes ago', 'Il y a 10 minutes'],
      'نصيحة اليوم: الإكثار من شرب الماء في فصل الصيف يحمي من الجفاف ويحسن صحة الكلى 🌿💧': ['Today’s tip: Drinking plenty of water in summer helps prevent dehydration and supports kidney health 🌿💧', 'Conseil du jour : boire beaucoup d’eau en été aide à prévenir la déshydratation et favorise la santé rénale 🌿💧'],
      'نصيحة': ['Tip', 'Conseil'],
      'طبيبة': ['Doctor', 'Médecin'],
      'منذ 25 دقيقة': ['25 minutes ago', 'Il y a 25 minutes'],
      'التغذية السليمة هي أساس الصحة الجيدة. تناولوا الخضروات والفواكه يومياً 🥗🍎': ['Good nutrition is the foundation of health. Eat vegetables and fruit every day 🥗🍎', 'Une bonne alimentation est la base de la santé. Mangez des légumes et des fruits chaque jour 🥗🍎'],
      'منذ ساعة': ['1 hour ago', 'Il y a 1 heure'],
      'مرضى الضغط يجب عليهم متابعة قراءاتهم بانتظام وتجنب الأطعمة المالحة 🩺❤️': ['People with high blood pressure should monitor their readings regularly and avoid salty foods 🩺❤️', 'Les personnes souffrant d’hypertension doivent surveiller régulièrement leurs mesures et éviter les aliments salés 🩺❤️'],
      'أم محمد': ['Umm Mohammed', 'Oum Mohammed'],
      'مستخدمة': ['User', 'Utilisatrice'],
      'منذ ساعتين': ['2 hours ago', 'Il y a 2 heures'],
      'الحمد لله ابني تعافى بعد استشارة الدكتور حسن. شكراً منصة صحتك 🙏❤️': ['Thank God, my son recovered after consulting Dr. Hassan. Thank you, Sehatak platform 🙏❤️', 'Grâce à Dieu, mon fils s’est rétabli après avoir consulté le Dr Hassan. Merci à la plateforme Sehatak 🙏❤️'],
      'تجربة': ['Experience', 'Témoignage'],
      'شريك معتمد': ['Verified partner', 'Partenaire agréé'],
      'منذ 3 ساعات': ['3 hours ago', 'Il y a 3 heures'],
      'وصلتنا شحنة جديدة من الأدوية المستوردة. خصم 20% على جميع الأدوية لمدة أسبوع 💊✨': ['A new shipment of imported medicines has arrived. Get 20% off all medicines for one week 💊✨', 'Une nouvelle livraison de médicaments importés est arrivée. Profitez de 20 % de réduction sur tous les médicaments pendant une semaine 💊✨'],
