      'اعرض المسعفين المتاحين الآن حسب مناطق تواجدهم واطلب الاستجابة للطوارئ.': ['View available responders by location and request an emergency response.', 'Consultez les secouristes disponibles par zone et demandez une intervention d’urgence.'],
      'الجروح والنزيف': ['Wounds and bleeding', 'Plaies et saignements'],
      'اضغط على الجرح بقطعة قماش نظيفة، ارفع الجزء المصاب فوق مستوى القلب': ['Apply pressure to the wound with a clean cloth and raise the injured area above heart level.', 'Comprimez la plaie avec un linge propre et surélevez la partie blessée au-dessus du niveau du cœur.'],
      'الحروق': ['Burns', 'Brûlures'],
      'ضع المنطقة المحروقة تحت ماء بارد جارٍ لمدة 10-15 دقيقة': ['Cool the burn under cool running water for 10–15 minutes.', 'Refroidissez la brûlure sous l’eau fraîche courante pendant 10 à 15 minutes.'],
      'الكسور': ['Fractures', 'Fractures'],
      'ثبت العضو المصاب، لا تحاول تحريكه، اتصل بالإسعاف': ['Immobilize the injured limb, do not try to move it, and call emergency services.', 'Immobilisez le membre blessé, n’essayez pas de le déplacer et appelez les secours.'],
      'الاختناق': ['Choking', 'Étouffement'],
      'استخدم مناورة هيمليك: ضع قبضة يدك فوق السرة وادفع للداخل وللأعلى': ['Use the Heimlich maneuver: place your fist above the navel and thrust inward and upward.', 'Utilisez la manœuvre de Heimlich : placez votre poing au-dessus du nombril et poussez vers l’intérieur et vers le haut.'],
      'اتصل بالطوارئ فوراً، لا تحاول إحداث التقيؤ إلا بإرشاد طبي': ['Call emergency services immediately. Do not induce vomiting unless instructed by a medical professional.', 'Appelez immédiatement les services d’urgence. Ne provoquez pas de vomissement sauf sur instruction d’un professionnel de santé.'],
      'الصدمة الكهربائية': ['Electric shock', 'Électrocution'],
      'افصل التيار، لا تلمس المصاب بيديك العاريتين، اتصل بالطوارئ': ['Disconnect the power. Do not touch the person with bare hands. Call emergency services.', 'Coupez le courant. Ne touchez pas la personne à mains nues. Appelez les services d’urgence.'],
