      'فعّل خدمة الموقع (GPS) في الهاتف ثم حاول مرة أخرى': ['Enable location services (GPS) on your phone, then try again.', 'Activez les services de localisation (GPS) sur votre téléphone, puis réessayez.'],
      'تم رفض إذن الموقع': ['Location permission was denied', 'L’autorisation de localisation a été refusée'],
