      'تم تحديد موقعك الحالي بدقة': ['Your current location was identified accurately', 'Votre position actuelle a été déterminée avec précision'],
      'تعذر تحديد موقعك. تأكد من تشغيل GPS والمحاولة مرة أخرى': ['Could not determine your location. Make sure GPS is enabled and try again.', 'Impossible de déterminer votre position. Vérifiez que le GPS est activé et réessayez.'],
