      'تحكم في الأذونات التي تمنحها للتطبيق. بعض الميزات قد لا تعمل بدون الأذونات الضرورية.': ['Manage the permissions you grant to the app. Some features may not work without the required permissions.', 'Gérez les autorisations accordées à l’application. Certaines fonctionnalités peuvent ne pas fonctionner sans les autorisations nécessaires.'],
      'الموقع الجغرافي': ['Location', 'Localisation'],
