      'ضروري': ['Required', 'Obligatoire'],
      'تحسين جودة النوم': ['Improve sleep quality', 'Améliorer la qualité du sommeil'],
      'بناءً على نمط نومك، نوصي بالنوم 7-8 ساعات يومياً والابتعاد عن الشاشات قبل النوم بساعة.': ['Based on your sleep pattern, we recommend 7–8 hours of sleep daily and avoiding screens for an hour before bedtime.', 'Selon votre rythme de sommeil, nous recommandons 7 à 8 heures de sommeil par jour et d’éviter les écrans dans l’heure précédant le coucher.'],
      'نظام غذائي صحي': ['Healthy diet', 'Alimentation saine'],
      'نوصي بتناول 5 حصص من الفواكه والخضار يومياً، وشرب 8 أكواب من الماء، وتقليل السكريات.': ['We recommend five servings of fruit and vegetables daily, drinking eight glasses of water, and reducing sugar intake.', 'Nous recommandons cinq portions de fruits et légumes par jour, huit verres d’eau et une réduction des sucres.'],
      'تمارين يومية': ['Daily exercise', 'Exercice quotidien'],
      'المشي 30 دقيقة يومياً يقلل خطر أمراض القلب والسكري. جرب صعود الدرج بدلاً من المصعد.': ['Walking for 30 minutes daily can reduce the risk of heart disease and diabetes. Try taking the stairs instead of the elevator.', 'Marcher 30 minutes par jour peut réduire le risque de maladies cardiaques et de diabète. Prenez les escaliers plutôt que l’ascenseur.'],
      'إدارة التوتر': ['Stress management', 'Gestion du stress'],
      'ممارسة التأمل والتنفس العميق 10 دقائق يومياً يساعد في تقليل التوتر وتحسين الصحة النفسية.': ['Practising meditation and deep breathing for 10 minutes daily can reduce stress and support mental well-being.', 'Pratiquer la méditation et la respiration profonde pendant 10 minutes par jour peut réduire le stress et favoriser le bien-être mental.'],
      'نوصي بإجراء فحص دوري كل 6 أشهر للاطمئنان على صحتك العامة والكشف المبكر عن الأمراض.': ['We recommend a checkup every six months to monitor your overall health and detect potential conditions early.', 'Nous recommandons un bilan tous les six mois pour surveiller votre santé générale et détecter précocement d’éventuels problèmes.'],
      'تذكير بالأدوية': ['Medication reminder', 'Rappel de médicaments'],
      'تذكر تناول أدويتك في المواعيد المحددة. استخدم تطبيقنا لتذكيرك بمواعيد الأدوية.': ['Remember to take your medication on schedule. Use our app to receive medication reminders.', 'Pensez à prendre vos médicaments aux heures prévues. Utilisez notre application pour recevoir des rappels.'],
