      "رعاية الحوامل": ["Pregnancy care", "Suivi de grossesse"],
      "متابعة الحمل من البداية حتى الولادة": ["Pregnancy care from the beginning through birth", "Suivi de grossesse du début jusqu’à l’accouchement"],
      "من 40": ["of 40", "sur 40"],
      "موعد تقديري: ": ["Estimated due date: ", "Date prévue estimée : "],
      "حددي أسبوع الحمل للاطلاع على مراحل المتابعة": ["Select your pregnancy week to view the follow-up stages", "Sélectionnez votre semaine de grossesse pour consulter les étapes du suivi"],
      "الرعاية الدورية للحمل": ["Routine pregnancy care", "Suivi régulier de la grossesse"],
      "الفحوصات والمتابعة": ["Tests and follow-up", "Examens et suivi"],
      "نصائح الحمل": ["Pregnancy tips", "Conseils de grossesse"],
      "متى تطلبين رعاية عاجلة؟": ["When should you seek urgent care?", "Quand demander des soins urgents ?"],
      "نزيف مهبلي شديد، ألم شديد أو مستمر، ضيق تنفس شديد، فقدان الوعي، صداع شديد مع اضطراب الرؤية، أو نقص ملحوظ في حركة الجنين بعد أن أصبحت الحركة منتظمة: تواصلي مع الرعاية الطبية العاجلة أو الطوارئ وفق حالتك.": ["Seek urgent medical care or emergency services if you have heavy vaginal bleeding, severe or persistent pain, severe shortness of breath, loss of consciousness, a severe headache with vision changes, or a noticeable decrease in fetal movement after a regular pattern has been established.", "Consultez en urgence ou contactez les services d’urgence en cas de saignement vaginal abondant, de douleur intense ou persistante, d’essoufflement sévère, de perte de connaissance, de fort mal de tête avec troubles visuels ou de diminution notable des mouvements du bébé après l’établissement d’un rythme régulier."],
      "هذه الشاشة مخصصة للحمل والنساء والتوليد فقط، ولا تخلط بياناتها مع شاشة صحة الطفل أو شاشة صحة المرأة العامة. جدول الزيارات والفحوصات قد يتغير حسب حالة الأم والجنين وإرشادات البلد والطبيب.": ["This screen is dedicated to pregnancy and obstetric care. It keeps pregnancy information separate from child-health and general women's-health screens. Visit and test schedules may vary according to the mother’s and baby’s condition, local guidance, and the clinician’s advice.", "Cet écran est consacré à la grossesse et à l’obstétrique. Les données de grossesse restent distinctes des écrans consacrés à la santé de l’enfant et à la santé générale des femmes. Le calendrier des visites et des examens peut varier selon l’état de la mère et du bébé, les recommandations locales et l’avis du professionnel de santé."],
      "حتى 12 أسبوعاً: بداية المتابعة وتقييم التاريخ الصحي والفحوصات المناسبة.": ["Up to 12 weeks: begin prenatal care, review medical history, and arrange appropriate tests.", "Jusqu’à 12 semaines : commencer le suivi prénatal, examiner les antécédents médicaux et prévoir les examens appropriés."],
      "20 أسبوعاً: متابعة نمو الجنين وتقييم الحمل والفحص المناسب حسب الخطة الطبية.": ["20 weeks: monitor fetal growth, assess the pregnancy, and arrange appropriate screening according to the care plan.", "20 semaines : surveiller la croissance du bébé, évaluer la grossesse et prévoir les examens appropriés selon le plan de soins."],
      "26 أسبوعاً: متابعة الأم والجنين ومراجعة نتائج الفحوصات والتغذية والأعراض.": ["26 weeks: review the health of the mother and baby, test results, nutrition, and symptoms.", "26 semaines : faire le point sur la santé de la mère et du bébé, les résultats des examens, l’alimentation et les symptômes."],
      "30 أسبوعاً: متابعة الضغط والوزن ونمو الجنين والاستعداد للثلث الأخير.": ["30 weeks: monitor blood pressure, weight, and fetal growth, and prepare for the final trimester.", "30 semaines : surveiller la tension artérielle, le poids et la croissance du bébé, et préparer le dernier trimestre."],
      "34 أسبوعاً: مراجعة خطة الولادة والاستعداد للطوارئ والرضاعة.": ["34 weeks: review the birth plan and prepare for emergencies and breastfeeding.", "34 semaines : revoir le projet de naissance et se préparer aux urgences et à l’allaitement."],
      "36 أسبوعاً: متابعة أقرب للولادة وتقييم وضع الجنين حسب الحالة.": ["36 weeks: arrange closer follow-up and assess the baby's position as appropriate.", "36 semaines : prévoir un suivi plus rapproché et évaluer la position du bébé si nécessaire."],
      "38 أسبوعاً: متابعة علامات المخاض وخطة الولادة حسب تقييم الفريق الطبي.": ["38 weeks: review signs of labor and the birth plan with the care team.", "38 semaines : examiner les signes du travail et le projet de naissance avec l’équipe soignante."],
      "40 أسبوعاً: تقييم الحمل وخطة المتابعة أو الولادة حسب حالة الأم والجنين.": ["40 weeks: assess the pregnancy and agree on a follow-up or birth plan based on the mother’s and baby's condition.", "40 semaines : évaluer la grossesse et convenir d’un suivi ou d’un plan d’accouchement selon l’état de la mère et du bébé."],
      "تحاليل الدم والبول الأساسية وفق تقييم مقدم الرعاية.": ["Basic blood and urine tests as assessed by the healthcare professional.", "Analyses sanguines et urinaires de base selon l’évaluation du professionnel de santé."],
      "قياس ضغط الدم والوزن في زيارات المتابعة.": ["Check blood pressure and weight at follow-up visits.", "Mesurer la tension artérielle et le poids lors des consultations de suivi."],
      "فحص سكر الحمل عادةً في منتصف الحمل وفق الخطة الطبية.": ["Gestational diabetes screening, usually midway through pregnancy, according to the care plan.", "Dépistage du diabète gestationnel, généralement au milieu de la grossesse, selon le plan de soins."],
      "فحوصات العدوى وفق الإرشادات المحلية والتاريخ الصحي.": ["Infection screening according to local guidance and medical history.", "Dépistage des infections selon les recommandations locales et les antécédents médicaux."],
      "التصوير بالموجات فوق الصوتية وفق التوقيت والخطة الطبية.": ["Ultrasound scans according to the recommended timing and care plan.", "Échographies selon le calendrier recommandé et le plan de soins."],
      "متابعة نمو الجنين وحركته في النصف الثاني من الحمل حسب التقييم السريري.": ["Monitor fetal growth and movement during the second half of pregnancy as clinically advised.", "Surveiller la croissance et les mouvements du bébé pendant la seconde moitié de la grossesse selon l’évaluation clinique."],
      "ابدئي المتابعة مبكراً بعد معرفة الحمل ولا تتركي الزيارات الدورية.": ["Start prenatal care early after confirming pregnancy and attend regular visits.", "Commencez le suivi prénatal dès la confirmation de la grossesse et respectez les consultations régulières."],
      "اتبعي خطة التغذية والمكملات التي يحددها مقدم الرعاية.": ["Follow the nutrition and supplement plan recommended by your healthcare professional.", "Suivez le programme alimentaire et les compléments recommandés par votre professionnel de santé."],
      "احرصي على النشاط البدني المناسب للحمل إذا لم توجد موانع طبية، وخذي قسطاً كافياً من الراحة.": ["Stay physically active in ways that are suitable for pregnancy if there are no medical restrictions, and get enough rest.", "Pratiquez une activité physique adaptée à la grossesse en l’absence de contre-indication médicale et reposez-vous suffisamment."],
      "تجنبي التدخين والكحول والمواد الضارة، وراجعي الأدوية الحالية مع الطبيب أو الصيدلي.": ["Avoid smoking, alcohol, and harmful substances. Review current medicines with your doctor or pharmacist.", "Évitez le tabac, l’alcool et les substances nocives. Vérifiez vos traitements actuels avec votre médecin ou votre pharmacien."],
      "جهزي خطة للولادة والنقل والطوارئ ومكان الرعاية قبل نهاية الحمل.": ["Prepare a birth, transport, emergency, and care-location plan before the end of pregnancy.", "Préparez avant la fin de la grossesse un plan pour l’accouchement, le transport, les urgences et le lieu de prise en charge."],
      "بعد الولادة تستمر الرعاية للأم والطفل وتشمل الرضاعة والصحة النفسية والمتابعة الطبية.": ["Care continues for both mother and baby after birth and includes breastfeeding, mental health, and medical follow-up.", "Après la naissance, les soins se poursuivent pour la mère et le bébé et comprennent l’allaitement, la santé mentale et le suivi médical."],
