      'البحث عن طبيب عيون': ['Find an eye doctor', 'Rechercher un ophtalmologue'],
      'صحة العين': ['Eye health', 'Santé oculaire'],
      'رعاية العين': ['Eye care', 'Soins des yeux'],
      'اختبارات داخلية ومتابعة مع طبيب العيون عند الحاجة.': ['In-app screening tools and follow-up with an eye doctor when needed.', 'Tests intégrés et suivi par un ophtalmologue si nécessaire.'],
      'الاختبارات والخدمات': ['Tests and services', 'Tests et services'],
      'اختبار حدة البصر': ['Visual acuity test', 'Test d’acuité visuelle'],
      'اختبار النظر التفاعلي داخل التطبيق': ['Interactive vision test in the app', 'Test de vision interactif dans l’application'],
      'فحص تمييز الألوان': ['Color vision screening', 'Dépistage de la vision des couleurs'],
      'إرشادات وفحص أولي للأعراض': ['Guidance and initial symptom screening', 'Conseils et première évaluation des symptômes'],
      'اختبار تمييز الألوان يعطي مؤشراً أولياً ولا يغني عن فحص طبي متخصص.': ['The color vision test is an initial indicator and does not replace a specialist examination.', 'Le test de vision des couleurs donne une première indication et ne remplace pas un examen spécialisé.'],
      'إذا كانت صعوبة تمييز الألوان جديدة أو تؤثر على حياتك اليومية، احجز موعداً مع طبيب عيون.': ['If color-vision difficulty is new or affects daily life, book an appointment with an eye doctor.', 'Si les difficultés de perception des couleurs sont récentes ou affectent votre quotidien, prenez rendez-vous avec un ophtalmologue.'],
      'فحص جفاف العين': ['Dry eye screening', 'Dépistage de la sécheresse oculaire'],
      'تقييم أولي للأعراض ونصائح العناية': ['Initial symptom assessment and care tips', 'Évaluation initiale des symptômes et conseils de soins'],
      'من الأعراض الشائعة الجفاف والحرقان والشعور بوجود جسم غريب أو زيادة الدموع.': ['Common symptoms include dryness, burning, a foreign-body sensation, or excessive tearing.', 'Les symptômes courants comprennent la sécheresse, les brûlures, la sensation de corps étranger ou un larmoiement excessif.'],
      'الأعراض المستمرة أو المصحوبة بألم أو تغير في الرؤية تحتاج إلى تقييم طبي.': ['Persistent symptoms, pain, or vision changes require medical assessment.', 'Les symptômes persistants, la douleur ou les changements de vision nécessitent une évaluation médicale.'],
      'قاعدة 20-20-20 عند استخدام الشاشات لفترات طويلة.': ['Follow the 20-20-20 rule when using screens for long periods.', 'Appliquez la règle 20-20-20 lors d’une utilisation prolongée des écrans.'],
      'احرص على الإضاءة المناسبة وخذ فواصل منتظمة.': ['Use suitable lighting and take regular breaks.', 'Privilégiez un éclairage adapté et faites des pauses régulières.'],
      'الفحص الطبي الدوري مهم خصوصاً عند وجود أعراض أو عوامل خطورة.': ['Regular eye examinations are important, especially when symptoms or risk factors are present.', 'Les examens réguliers sont importants, surtout en présence de symptômes ou de facteurs de risque.'],
      'عرض أطباء العيون والحجز': ['View eye doctors and book', 'Voir les ophtalmologues et prendre rendez-vous'],
