      "اختبار تفاعلي أولي لتمييز اتجاه فتحة الحرف. اجلس بوضع مريح، حافظ على مسافة ثابتة من الشاشة، لا تكبّر العرض، واستخدم إضاءة جيدة. لا يغني الاختبار عن فحص حدة البصر بأدوات سريرية.": ["A preliminary interactive test to identify the direction of the letter opening. Sit comfortably, keep a steady distance from the screen, do not zoom in, and use good lighting. This test does not replace a clinical visual acuity exam.", "Un test interactif préliminaire pour identifier la direction de l’ouverture de la lettre. Asseyez-vous confortablement, gardez une distance constante de l’écran, ne zoomez pas et utilisez un bon éclairage. Ce test ne remplace pas un examen clinique de l’acuité visuelle."],
      "إلى أي اتجاه تتجه فتحة الحرف؟": ["Which direction is the letter opening facing?", "Dans quelle direction est orientée l’ouverture de la lettre ?"],
      "تقييم جودة النظر": ["Vision quality assessment", "Évaluation de la qualité de la vision"],
      "هذا تقييم أولي داخل التطبيق ولا يقيس حدة البصر بوحدة سريرية، ولا يحدد الحاجة إلى نظارة أو علاج. إذا كان لديك تشوش مستمر، ازدواجية، ألم، ومضات أو فقد مفاجئ للرؤية، اطلب تقييماً طبياً ولا تعتمد على الاختبار.": ["This is an initial in-app assessment. It does not measure clinical visual acuity or determine whether you need glasses or treatment. If you have persistent blurred or double vision, pain, flashes, or sudden vision loss, seek medical evaluation and do not rely on this test.", "Il s’agit d’une première évaluation dans l’application. Elle ne mesure pas l’acuité visuelle selon une unité clinique et ne détermine pas le besoin de lunettes ou de traitement. En cas de vision floue persistante ou double, de douleur, d’éclairs lumineux ou de perte soudaine de la vision, consultez un médecin et ne vous fiez pas à ce test."],
