      "اكتشاف علاج جديد لمرض السكري من النوع الثاني": ["A new treatment for type 2 diabetes has been discovered", "Découverte d’un nouveau traitement contre le diabète de type 2"],
      "توصل فريق من الباحثين إلى علاج جديد لمرض السكري من النوع الثاني يحسن مستويات السكر في الدم بنسبة 40%.": ["A research team has developed a new treatment for type 2 diabetes that improves blood glucose levels by 40%.", "Une équipe de chercheurs a mis au point un nouveau traitement du diabète de type 2 qui améliore la glycémie de 40 %."],
      "دراسة: المشي 30 دقيقة يومياً يقلل خطر الاكتئاب": ["Study: Walking 30 minutes a day reduces depression risk", "Étude : marcher 30 minutes par jour réduit le risque de dépression"],
      "دراسة جديدة تظهر أن المشي لمدة 30 دقيقة يومياً يمكن أن يقلل من خطر الاكتئاب بنسبة تصل إلى 25%.": ["A new study suggests that walking for 30 minutes daily may reduce the risk of depression by up to 25%.", "Une nouvelle étude indique que marcher 30 minutes par jour pourrait réduire le risque de dépression jusqu’à 25 %."],
      "تطوير روبوت جراحي دقيق لعمليات القلب المفتوح": ["A precision surgical robot is developed for open-heart surgery", "Un robot chirurgical de précision est développé pour la chirurgie à cœur ouvert"],
      "تقنية جديدة تسمح بإجراء عمليات القلب المفتوح بدقة متناهية باستخدام روبوت جراحي متطور.": ["A new technology enables highly precise open-heart procedures using an advanced surgical robot.", "Une nouvelle technologie permet des interventions à cœur ouvert très précises grâce à un robot chirurgical avancé."],
      "المؤتمر العالمي للصحة ينطلق في الرياض": ["World Health Conference opens in Riyadh", "Le Congrès mondial de la santé s’ouvre à Riyad"],
      "انطلاق فعاليات المؤتمر العالمي للصحة بمشاركة أكثر من 2000 خبير من جميع أنحاء العالم.": ["The World Health Conference begins with more than 2,000 experts from around the world.", "Le Congrès mondial de la santé débute avec la participation de plus de 2 000 experts du monde entier."],
      "أبحاث جديدة عن لقاح كورونا طويل الأمد": ["New research on a long-lasting COVID-19 vaccine", "Nouvelles recherches sur un vaccin durable contre la COVID-19"],
      "أبحاث جديدة تظهر فعالية لقاح كورونا في توفير حماية طويلة الأمد تصل إلى 18 شهراً.": ["New research indicates that a COVID-19 vaccine may provide long-lasting protection for up to 18 months.", "De nouvelles recherches indiquent qu’un vaccin contre la COVID-19 pourrait offrir une protection durable jusqu’à 18 mois."],
      "زيادة حالات الحساسية الغذائية بين الأطفال": ["Food allergies are increasing among children", "Les allergies alimentaires augmentent chez les enfants"],
      "تقارير طبية تشير إلى زيادة ملحوظة في حالات الحساسية الغذائية بين الأطفال في السنوات الأخيرة.": ["Medical reports indicate a notable rise in food allergies among children in recent years.", "Des rapports médicaux signalent une hausse notable des allergies alimentaires chez les enfants ces dernières années."],
      "تطوير جهاز محمول لقياس ضغط الدم بدقة عالية": ["A portable device is developed to measure blood pressure accurately", "Un appareil portable est développé pour mesurer la tension artérielle avec précision"],
      "جهاز محمول جديد يمكنه قياس ضغط الدم بدقة عالية تصل إلى 98% ومزامنة البيانات مع الهواتف الذكية.": ["A new portable device can measure blood pressure with up to 98% accuracy and sync data with smartphones.", "Un nouvel appareil portable peut mesurer la tension artérielle avec une précision allant jusqu’à 98 % et synchroniser les données avec les smartphones."],
      "دراسة: النظام الغذائي المتوسطي يعزز صحة الدماغ": ["Study: The Mediterranean diet supports brain health", "Étude : le régime méditerranéen favorise la santé cérébrale"],
      "دراسة جديدة تؤكد أن النظام الغذائي المتوسطي يساهم في تعزيز صحة الدماغ وتأخير ظهور علامات الشيخوخة.": ["A new study confirms that the Mediterranean diet helps support brain health and delay signs of aging.", "Une nouvelle étude confirme que le régime méditerranéen contribue à la santé cérébrale et retarde les signes du vieillissement."],
      "المؤتمر العربي للصحة النفسية ينعقد في دبي": ["Arab Mental Health Conference takes place in Dubai", "Le Congrès arabe de santé mentale se tient à Dubaï"],
      "انعقاد المؤتمر العربي للصحة النفسية بمشاركة أطباء ومختصين من 15 دولة عربية.": ["The Arab Mental Health Conference is held with doctors and specialists from 15 Arab countries.", "Le Congrès arabe de santé mentale réunit des médecins et spécialistes de 15 pays arabes."],
      "نتائج مبشرة لتجارب لقاح الملاريا": ["Promising results from malaria vaccine trials", "Résultats prometteurs des essais d’un vaccin contre le paludisme"],
      "نتائج تجارب لقاح الملاريا تظهر فعالية بنسبة 75% في الوقاية من المرض في المراحل الأولى من التجارب.": ["Malaria vaccine trial results show 75% effectiveness in preventing the disease during the early trial stages.", "Les essais du vaccin contre le paludisme montrent une efficacité de 75 % dans la prévention de la maladie aux premiers stades des essais."],
      "تأثير التلوث البيئي على صحة الجهاز التنفسي": ["The impact of environmental pollution on respiratory health", "L’impact de la pollution environnementale sur la santé respiratoire"],
      "تقرير منظمة الصحة العالمية يحذر من تأثير التلوث البيئي المتزايد على صحة الجهاز التنفسي.": ["A World Health Organization report warns about the growing impact of environmental pollution on respiratory health.", "Un rapport de l’Organisation mondiale de la santé met en garde contre l’impact croissant de la pollution sur la santé respiratoire."],
      "اختراق علمي في علاج أمراض المناعة الذاتية": ["A scientific breakthrough in treating autoimmune diseases", "Une avancée scientifique dans le traitement des maladies auto-immunes"],
      "اختراق علمي كبير في فهم وعلاج أمراض المناعة الذاتية من خلال تقنيات جديدة لتعديل الجينات.": ["A major scientific breakthrough improves understanding and treatment of autoimmune diseases through new gene-editing techniques.", "Une avancée scientifique majeure améliore la compréhension et le traitement des maladies auto-immunes grâce à de nouvelles techniques de modification génétique."],
      "أضف قياساتك الصحية لاحتساب المؤشر.": ["Add your health measurements to calculate the score.", "Ajoutez vos mesures de santé pour calculer le score."],
