      'نجمع البيانات الأساسية مثل الاسم والبريد الإلكتروني والمعلومات الصحية الضرورية لتقديم الخدمات.': ['We collect essential information such as your name, email address and the health information needed to provide our services.', 'Nous collectons les informations essentielles telles que votre nom, votre adresse e-mail et les données de santé nécessaires à nos services.'],
      'استخدام البيانات': ['Data use', 'Utilisation des données'],
      'نستخدم بياناتك لتقديم خدمات صحية مخصصة وتحسين تجربتك في التطبيق.': ['We use your data to provide personalized health services and improve your app experience.', 'Nous utilisons vos données pour fournir des services de santé personnalisés et améliorer votre expérience dans l’application.'],
      'لا نشارك بياناتك مع أطراف ثالثة إلا بموافقتك الصريحة أو عند الضرورة القانونية.': ['We do not share your data with third parties without your explicit consent, except where legally required.', 'Nous ne partageons pas vos données avec des tiers sans votre consentement explicite, sauf obligation légale.'],
      'أمن البيانات': ['Data security', 'Sécurité des données'],
      'نتخذ إجراءات أمنية متقدمة لحماية بياناتك من الوصول غير المصرح به.': ['We use security measures to protect your data from unauthorized access.', 'Nous appliquons des mesures de sécurité pour protéger vos données contre tout accès non autorisé.'],
      'يمكنك طلب حذف بياناتك في أي وقت من خلال التواصل مع فريق الدعم.': ['You can request deletion of your data at any time by contacting our support team.', 'Vous pouvez demander la suppression de vos données à tout moment en contactant notre assistance.'],
      "متابعة طبية، راحة": ["Medical follow-up and rest", "Suivi médical et repos"],
