      'جرّب اسم طبيب أو تخصصاً طبياً.': ['Try a doctor\'s name or a medical specialty.', 'Essayez un nom de médecin ou une spécialité médicale.'],
      'هذه الجولة ستظهر مرة واحدة فقط على هذا الجهاز.': ['This tour will appear only once on this device.', 'Cette visite ne s’affichera qu’une seule fois sur cet appareil.'],
      'انتهت الجولة — التسوق جاهز عندما تحتاجه.': ['Tour complete — shopping is ready whenever you need it.', 'Visite terminée — la boutique est prête quand vous en avez besoin.'],
      'انتهت جولة المزيد — استكشف ما تحتاجه وقتما تشاء.': ['More tour complete — explore whenever you like.', 'Visite de la section Plus terminée — explorez à votre rythme.'],
      'اكتملت الجولة — ملفك الصحي أصبح أسهل في الاستكشاف.': ['Tour complete — your health profile is now easier to explore.', 'Visite terminée — votre dossier de santé est désormais plus facile à parcourir.'],
      'ابحث عن طبيب': ['Find a doctor', 'Rechercher un médecin'],
      'اكتب اسم الطبيب أو كلمة مرتبطة بالتخصص للوصول للنتائج بسرعة.': ['Enter a doctor\'s name or a specialty-related term to find results quickly.', 'Saisissez le nom d’un médecin ou un terme lié à sa spécialité pour trouver rapidement des résultats.'],
      'التخصصات': ['Specialties', 'Spécialités'],
      'استخدم شريط التخصصات لتضييق قائمة الأطباء حسب المجال الطبي.': ['Use the specialties bar to narrow the doctor list by medical field.', 'Utilisez la barre des spécialités pour filtrer les médecins par domaine médical.'],
      'هذه المنطقة تعرض الأطباء والبيانات التي يوفرها النظام عن التوفر والتقييم.': ['This area displays doctors and the availability and rating information provided by the system.', 'Cette zone affiche les médecins ainsi que les informations de disponibilité et d’évaluation fournies par le système.'],
      'استشاري': ['Consultant', 'Consultant'],
      'افتح بطاقة الطبيب للوصول إلى التفاصيل والملف والخدمات المتاحة.': ['Open the doctor\'s card to view details, profile, and available services.', 'Ouvrez la fiche du médecin pour consulter ses détails, son profil et les services disponibles.'],
      'التواصل': ['Contact', 'Contact'],
      'من أدوات بطاقة الطبيب يمكنك بدء الدردشة أو الاتصال عندما تكون الخدمة متاحة.': ['Use the doctor card tools to start a chat or call when the service is available.', 'Depuis la fiche du médecin, vous pouvez démarrer une discussion ou un appel lorsque le service est disponible.'],
      'تحديث النتائج': ['Refresh results', 'Actualiser les résultats'],
      'اسحب القائمة للأسفل لتحديث أحدث بيانات الأطباء.': ['Pull down the list to refresh the latest doctor information.', 'Faites glisser la liste vers le bas pour actualiser les dernières informations sur les médecins.'],
      'انتهت جولة الأطباء.': ['Doctors tour complete.', 'Visite des médecins terminée.'],
      'متجر أدوية صحتك': ['Sehatak medicine store', 'Boutique de médicaments Sehatak'],
      'هنا تتصفح المنتجات المنشورة والمعتمدة داخل متجر صحتك.': ['Browse published and approved products in the Sehatak store here.', 'Parcourez ici les produits publiés et approuvés dans la boutique Sehatak.'],
      'تابع العناصر المضافة وافتح السلة لمراجعة اختياراتك.': ['Track added items and open the cart to review your selections.', 'Suivez les articles ajoutés et ouvrez le panier pour vérifier votre sélection.'],
      'ابحث باسم الدواء': ['Search by medicine name', 'Rechercher par nom de médicament'],
      'البحث عن الدواء': ['Find medicine', 'Rechercher un médicament'],
      'ابحث باسم الدواء أو المادة الفعالة أو الفئة.': ['Search by medicine name, active ingredient, or category.', 'Recherchez par nom de médicament, principe actif ou catégorie.'],
      'فئات المنتجات': ['Product categories', 'Catégories de produits'],
      'استخدم الفئات لتقليل النتائج والوصول للنوع الذي تحتاجه.': ['Use categories to narrow the results and find the type you need.', 'Utilisez les catégories pour affiner les résultats et trouver le type recherché.'],
      'تصفح المنتجات الفعلية والسعر والتوفر ومصدر البيع.': ['Browse available products, prices, stock status, and seller information.', 'Consultez les produits disponibles, leurs prix, leur stock et les informations du vendeur.'],
      'راجع معلومات المنتج ومصدره وتوفره قبل اتخاذ قرار الإضافة.': ['Review the product information, source, and availability before adding it.', 'Vérifiez les informations, la provenance et la disponibilité du produit avant de l’ajouter.'],
      'الإضافة للسلة': ['Add to cart', 'Ajouter au panier'],
      'عندما يكون المنتج متوفراً استخدم زر الإضافة لبناء طلبك.': ['When a product is available, use the add button to build your order.', 'Lorsqu’un produit est disponible, utilisez le bouton d’ajout pour composer votre commande.'],
      'انتهت جولة الصيدلية.': ['Pharmacy tour complete.', 'Visite de la pharmacie terminée.'],
