      'الفئات': ['Categories', 'Catégories'],
      'اختر فئة مثل الدم أو الهرمونات أو الفيتامينات لتصفية النتائج.': ['Choose a category such as blood, hormones, or vitamins to filter results.', 'Choisissez une catégorie comme le sang, les hormones ou les vitamines pour filtrer les résultats.'],
      'هنا تظهر بيانات المختبرات المتاحة من النظام.': ['Available laboratory information from the system appears here.', 'Les informations des laboratoires disponibles dans le système apparaissent ici.'],
      'افتح البطاقة للتعرف على الخدمات والتفاصيل وإجراءات الحجز.': ['Open a card to view services, details, and booking options.', 'Ouvrez une fiche pour consulter les services, les détails et les options de réservation.'],
      'الخدمة المنزلية': ['Home service', 'Service à domicile'],
      'انتقل إلى تبويب الخدمة المنزلية لاستعراض المختبرات التي تدعم الوصول للمنزل.': ['Select the home-service tab to browse laboratories that offer home visits.', 'Sélectionnez l’onglet du service à domicile pour voir les laboratoires proposant des visites à domicile.'],
      'انتهت جولة المختبرات.': ['Laboratories tour complete.', 'Visite des laboratoires terminée.'],
      'ابدأ من بطاقة الحساب لمراجعة بياناتك الأساسية وملفك الصحي.': ['Start with the account card to review your basic information and health profile.', 'Commencez par la carte du compte pour consulter vos informations de base et votre dossier de santé.'],
      'راجع نوع الباقة والخدمات المرتبطة بها عندما تكون معروضة في الملف.': ['Review your plan type and its associated services when shown in your profile.', 'Consultez votre formule et les services associés lorsqu’ils sont affichés dans votre profil.'],
      'راجع أهم القياسات الصحية وأدوات التتبع المرتبطة بها.': ['Review your key health measurements and related tracking tools.', 'Consultez vos principales mesures de santé et les outils de suivi associés.'],
      'اختصارات مباشرة للأدوات الأكثر استخداماً مثل المواعيد والأدوية.': ['Quick links to frequently used tools such as appointments and medicines.', 'Accès rapides aux outils les plus utilisés, comme les rendez-vous et les médicaments.'],
      'استكشف الخدمات الصحية المرتبطة بحسابك من مكان واحد.': ['Explore the health services linked to your account in one place.', 'Découvrez en un seul endroit les services de santé associés à votre compte.'],
      'المزمنة': ['Chronic conditions', 'Maladies chroniques'],
      'تابع المعلومات الصحية المزمنة المسجلة داخل ملفك.': ['Review chronic health information recorded in your profile.', 'Consultez les informations relatives aux maladies chroniques enregistrées dans votre dossier.'],
      'راجع سجلات التطعيمات ومعلوماتها.': ['Review your vaccination records and information.', 'Consultez vos dossiers et informations de vaccination.'],
      'راجع معلومات الحساسية المسجلة لتبقى بيانات الرعاية واضحة.': ['Review recorded allergy information to keep your care details clear.', 'Consultez les allergies enregistrées afin de conserver des informations de soins claires.'],
      'اكتملت جولة الملف الصحي.': ['Health profile tour complete.', 'Visite du dossier de santé terminée.'],
      'من هنا تصل إلى ملفك الشخصي ومعلومات حسابك الأساسية.': ['Access your profile and basic account information here.', 'Accédez ici à votre profil et aux informations essentielles de votre compte.'],
      'اختصارات مباشرة لأدوات تتبع الضغط والسكر والوزن والنوم وغيرها.': ['Quick links to track blood pressure, glucose, weight, sleep, and more.', 'Accès rapides au suivi de la tension artérielle, de la glycémie, du poids, du sommeil et plus encore.'],
      'اختر فئة لتظهر الخدمات المرتبطة بها فقط.': ['Choose a category to display only its related services.', 'Choisissez une catégorie pour afficher uniquement les services associés.'],
      'هنا تجد الأدوات والخدمات الإضافية من الخرائط والتأمين إلى الدعم والإعدادات.': ['Find additional tools and services here, from maps and insurance to support and settings.', 'Retrouvez ici des outils et services supplémentaires, des cartes et assurances à l’assistance et aux paramètres.'],
      'زر تسجيل الخروج موجود في نهاية الصفحة عندما تحتاج إلى إنهاء الجلسة.': ['The sign-out button is at the bottom of the page when you need to end your session.', 'Le bouton de déconnexion se trouve en bas de la page lorsque vous souhaitez terminer votre session.'],
