      'هنا تظهر المختبرات الفعلية من النظام، مع البيانات المتاحة لكل منشأة.': ['Laboratories available in the system appear here with the information provided for each facility.', 'Les laboratoires disponibles dans le système apparaissent ici avec les informations fournies pour chaque établissement.'],
      'بطاقة المختبر': ['Laboratory card', 'Fiche du laboratoire'],
      'افتح بطاقة المختبر للتعرف على خدماته وتفاصيله والانتقال إلى إجراءات الحجز المتاحة.': ['Open a laboratory card to review its services and details and continue to available booking options.', 'Ouvrez la fiche d’un laboratoire pour consulter ses services et ses détails, puis accéder aux options de réservation.'],
      'انتقل إلى تبويب الخدمة المنزلية عندما تريد استعراض المختبرات التي تدعم الوصول إلى المنزل.': ['Open the home-service tab to browse laboratories that offer visits at home.', 'Ouvrez l’onglet du service à domicile pour consulter les laboratoires proposant des visites à domicile.'],
      'انتهت الجولة — اختر المختبر الأنسب لك.': ['Tour complete — choose the laboratory that suits you.', 'Visite terminée — choisissez le laboratoire qui vous convient.'],
      'مساحتك الشخصية': ['Your personal space', 'Votre espace personnel'],
      'من هنا تصل إلى ملفك الشخصي وتراجع معلومات حسابك الأساسية بسرعة.': ['Access your profile and review your basic account information here.', 'Accédez ici à votre profil et consultez rapidement les informations essentielles de votre compte.'],
      'اختصارات مباشرة لأدوات تتبع المؤشرات الصحية مثل الضغط والسكر والوزن والنوم.': ['Quick links to health tracking tools such as blood pressure, glucose, weight, and sleep.', 'Accès rapides aux outils de suivi de la santé : tension artérielle, glycémie, poids et sommeil.'],
      'تصنيف الخدمات': ['Service categories', 'Catégories de services'],
      'بدلاً من البحث في قائمة طويلة، اختر فئة لتظهر الخدمات المرتبطة بها فقط.': ['Instead of searching a long list, choose a category to show only related services.', 'Au lieu de parcourir une longue liste, choisissez une catégorie pour afficher uniquement les services associés.'],
      'كل خدمات صحتك': ['All Sehatak services', 'Tous les services Sehatak'],
      'هنا تجد الأدوات والخدمات الإضافية، من الخرائط والتأمين إلى الدعم والإعدادات.': ['Find additional tools and services here, from maps and insurance to support and settings.', 'Retrouvez ici des outils et services supplémentaires, des cartes et assurances à l’assistance et aux paramètres.'],
      'الخروج بأمان': ['Sign out securely', 'Déconnexion sécurisée'],
      'زر تسجيل الخروج موجود في نهاية الصفحة عندما تحتاج إلى إنهاء الجلسة على الجهاز.': ['The sign-out button is at the bottom of the page when you need to end your session on this device.', 'Le bouton de déconnexion se trouve en bas de la page lorsque vous souhaitez terminer votre session sur cet appareil.'],
