      'قم بتوثيق حسابك لزيادة الثقة مع المرضى': ['Verify your account to build trust with patients', 'Vérifiez votre compte pour renforcer la confiance des patients'],
      'أهلاً بك في منصة صحتك للصيدليات': ['Welcome to Sehatak for pharmacies', 'Bienvenue sur Sehatak pour les pharmacies'],
