      'استقبل طلبات الفحوصات من المرضى': ['Receive test requests from patients', 'Recevez les demandes d’analyses des patients'],
      'وثق حسابك لزيادة ثقة المرضى في مختبرك': ['Verify your account to increase patient trust in your laboratory', 'Vérifiez votre compte pour renforcer la confiance des patients envers votre laboratoire'],
      'أهلاً بك في منصة صحتك للطب البيطري': ['Welcome to Sehatak veterinary care', 'Bienvenue sur Sehatak pour les soins vétérinaires'],
