      'سجل الأدوية قيد التطوير': ['Medication history is under development', 'L’historique des médicaments est en cours de développement'],
      'ابحث عن طبيبك': ['Find your doctor', 'Trouvez votre médecin'],
      'اكتب اسم الطبيب أو ما تبحث عنه للوصول إلى النتائج بسرعة، مع تحديث النتائج أثناء الكتابة.': ['Enter a doctor’s name or search term to find results quickly as you type.', 'Saisissez le nom d’un médecin ou un terme de recherche pour trouver rapidement des résultats au fil de la saisie.'],
      'التخصصات بين يديك': ['Specialties at your fingertips', 'Les spécialités à portée de main'],
      'صف التخصصات يساعدك على تضييق النتائج والعثور على الطبيب المناسب لاحتياجك.': ['Use the specialty row to narrow results and find the right doctor for your needs.', 'La liste des spécialités vous aide à affiner les résultats et à trouver le médecin adapté à vos besoins.'],
      'قائمة الأطباء': ['Doctors list', 'Liste des médecins'],
      'هنا تظهر النتائج الفعلية من النظام، مع معلومات التوفر والملف الطبي لكل طبيب.': ['Actual results from the system appear here, with each doctor’s availability and profile information.', 'Les résultats réels du système apparaissent ici, avec les disponibilités et le profil de chaque médecin.'],
      'بطاقة الطبيب': ['Doctor card', 'Fiche du médecin'],
      'افتح بطاقة الطبيب لاستعراض تفاصيله، تخصصه، حالته والخدمات المتاحة له.': ['Open a doctor’s card to review their details, specialty, status, and available services.', 'Ouvrez la fiche du médecin pour consulter ses détails, sa spécialité, son statut et les services disponibles.'],
      'تواصل مباشرة': ['Connect directly', 'Contact direct'],
      'عندما تكون الأدوات متاحة في بطاقة الطبيب، يمكنك بدء محادثة أو اتصال بطريقة مباشرة.': ['When available on the doctor’s card, you can start a chat or call directly.', 'Lorsque ces options sont disponibles sur la fiche du médecin, vous pouvez démarrer une discussion ou un appel directement.'],
      'حدّث النتائج': ['Refresh results', 'Actualiser les résultats'],
      'اسحب القائمة للتحديث والحصول على أحدث حالة للأطباء والبيانات المتاحة.': ['Pull down to refresh and get the latest doctor statuses and available information.', 'Tirez la liste vers le bas pour actualiser et obtenir les derniers statuts des médecins et les informations disponibles.'],
      'هنا تبدأ رحلة شراء الأدوية من المنتجات المنشورة والمعتمدة داخل متجر صحتك.': ['Start shopping for medicines from products published and approved in the Sehatak store.', 'Commencez vos achats parmi les produits publiés et approuvés dans la boutique Sehatak.'],
      'سلة مشترياتك': ['Your shopping cart', 'Votre panier'],
      'تابع عدد العناصر التي أضفتها وافتح السلة لمراجعة اختياراتك.': ['Track the items you have added and open the cart to review your selections.', 'Suivez les articles ajoutés et ouvrez le panier pour vérifier votre sélection.'],
      'ابحث عن الدواء': ['Find a medicine', 'Rechercher un médicament'],
      'ابحث بالاسم أو المادة الفعالة أو الفئة للوصول إلى المنتج بسرعة.': ['Search by name, active ingredient, or category to find a product quickly.', 'Recherchez par nom, substance active ou catégorie pour trouver rapidement un produit.'],
      'صفِّ النتائج': ['Filter results', 'Filtrer les résultats'],
      'استخدم فئات المنتجات لتقليل النتائج والتركيز على النوع الذي تحتاجه.': ['Use product categories to narrow results and focus on what you need.', 'Utilisez les catégories de produits pour affiner les résultats et vous concentrer sur ce dont vous avez besoin.'],
      'المنتجات المنشورة': ['Published products', 'Produits publiés'],
      'تصفح المنتجات الفعلية مع السعر، حالة المخزون، البائع ومعلومات الدواء المتاحة.': ['Browse available products with prices, stock status, seller, and available medicine information.', 'Parcourez les produits disponibles avec leurs prix, l’état du stock, le vendeur et les informations sur les médicaments.'],
      'تفاصيل المنتج': ['Product details', 'Détails du produit'],
      'راجع اسم الدواء ومعلوماته ومصدره وتوفره قبل إضافته إلى السلة.': ['Review the medicine name, information, source, and availability before adding it to your cart.', 'Vérifiez le nom du médicament, ses informations, sa provenance et sa disponibilité avant de l’ajouter au panier.'],
      'إذا كان المنتج متوفراً، استخدم زر الإضافة لبناء طلبك خطوة بخطوة.': ['If the product is available, use the add button to build your order step by step.', 'Si le produit est disponible, utilisez le bouton d’ajout pour composer votre commande étape par étape.'],
      'ابقَ على اطلاع': ['Stay informed', 'Restez informé'],
      'كل تنبيه مهم من صحتك يصل إلى هنا: مواعيد، رسائل، تحديثات ونتائج تحتاج انتباهك.': ['Important Sehatak alerts appear here: appointments, messages, updates, and results that need your attention.', 'Les alertes importantes de Sehatak apparaissent ici : rendez-vous, messages, mises à jour et résultats nécessitant votre attention.'],
      'اضغط التالي لنكتشف بقية واجهة صحتك.': ['Tap Next to explore the rest of Sehatak.', 'Appuyez sur Suivant pour découvrir le reste de Sehatak.'],
      'كل طلباتك في مكان واحد': ['All your orders in one place', 'Toutes vos commandes au même endroit'],
      'راجع الأدوية والمنتجات التي اخترتها، وتابع سلتك قبل إكمال طلبك.': ['Review the medicines and products you selected and check your cart before completing your order.', 'Vérifiez les médicaments et produits sélectionnés ainsi que votre panier avant de finaliser la commande.'],
      'ابحث بذكاء': ['Search smarter', 'Recherchez intelligemment'],
      'ابحث عن طبيب أو دواء أو خدمة بسرعة من البحث الموحد في أعلى الرئيسية.': ['Quickly find a doctor, medicine, or service using the unified search at the top of Home.', 'Trouvez rapidement un médecin, un médicament ou un service grâce à la recherche unifiée en haut de l’accueil.'],
      'نظرة سريعة على صحتك ونشاطك اليومي تساعدك على متابعة عاداتك ومؤشراتك باستمرار.': ['A quick view of your health and daily activity helps you keep track of your habits and vital signs.', 'Un aperçu de votre santé et de votre activité quotidienne vous aide à suivre vos habitudes et vos indicateurs.'],
      'الخدمات السريعة': ['Quick services', 'Services rapides'],
      'أقصر طريق إلى الخدمات الأكثر استخداماً، من الأطباء والطوارئ إلى المختبرات والصحة.': ['Quick access to frequently used services, from doctors and emergencies to laboratories and health.', 'Accédez rapidement aux services les plus utilisés, des médecins et urgences aux laboratoires et à la santé.'],
      'اكتشف الأطباء المتاحين، تخصصاتهم وملفاتهم، ثم اختر الخدمة المناسبة لك.': ['Discover available doctors, their specialties and profiles, then choose the service that suits you.', 'Découvrez les médecins disponibles, leurs spécialités et leurs profils, puis choisissez le service qui vous convient.'],
      'مساحة صحية للتفاعل والمشاركة واكتشاف محتوى مفيد داخل مجتمع صحتك.': ['A health space to interact, share, and discover useful content in the Sehatak community.', 'Un espace santé pour échanger, partager et découvrir du contenu utile au sein de la communauté Sehatak.'],
      'انتهت الجولة — يمكنك العودة لأي قسم في أي وقت.': ['Tour complete — you can return to any section at any time.', 'Visite terminée — vous pouvez revenir à n’importe quelle section à tout moment.'],
      'هذا هو مركز معلوماتك الأساسية. افتح ملفك لمراجعة بياناتك وتحديث ما تحتاجه.': ['This is the hub for your essential information. Open your profile to review and update your details.', 'Voici le centre de vos informations essentielles. Ouvrez votre profil pour consulter et mettre à jour vos données.'],
      'تعرف على نوع الباقة الحالية والخدمات المرتبطة بها من لوحة المستخدم.': ['View your current plan and its included services from your user dashboard.', 'Consultez votre forfait actuel et les services associés depuis votre tableau de bord.'],
      'راجع أهم مؤشراتك الصحية بسرعة، وافتح أي مؤشر للوصول إلى أدوات التتبع المرتبطة به.': ['Quickly review your key health indicators and open any indicator to access its tracking tools.', 'Consultez rapidement vos principaux indicateurs de santé et ouvrez-en un pour accéder aux outils de suivi associés.'],
      'اختصارات عملية لأكثر الأدوات استخداماً مثل المواعيد والأدوية والمختبرات.': ['Convenient shortcuts to frequently used tools such as appointments, medicines, and laboratories.', 'Raccourcis pratiques vers les outils les plus utilisés, comme les rendez-vous, les médicaments et les laboratoires.'],
      'مجموعة الخدمات التي تساعدك على إدارة الرعاية الصحية من مكان واحد.': ['A collection of services that helps you manage healthcare in one place.', 'Un ensemble de services pour gérer vos soins de santé depuis un seul endroit.'],
      'قسم مخصص لمتابعة المعلومات المتعلقة بالحالات المزمنة داخل ملفك الصحي.': ['A dedicated section for tracking information about chronic conditions in your health profile.', 'Une section dédiée au suivi des informations sur les maladies chroniques dans votre dossier de santé.'],
      'تابع معلومات التطعيمات والسجلات المرتبطة بها ضمن ملفك.': ['Track vaccination information and related records in your profile.', 'Suivez les informations de vaccination et les dossiers associés dans votre profil.'],
